INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.e', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO', 'e', 'promote the skill of listening intensively to a variety of texts for information and enjoyment', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
