INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.a', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI', 'a', 'identify prepositions of position and direction in sentences', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.b', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI', 'b', 'use prepositions correctly in oral and written contexts', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.c', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI', 'c', 'promote the use of prepositions for clarity in communication', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
