INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.a', 'ENGL.G4.WRITIN.T13_SPELLING', 'a', 'spell words with double consonants correctly for clarity of writing', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.b', 'ENGL.G4.WRITIN.T13_SPELLING', 'b', 'construct correct sentences using words with double consonants for cohesive writing', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_outcomes (code, substrand_code, letter, text, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.c', 'ENGL.G4.WRITIN.T13_SPELLING', 'c', 'realise the importance of writing words clearly and correctly in communication', 'kicd_verified') ON CONFLICT (code) DO NOTHING;
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 4, 'Say the target sounds of English clearly in words', ARRAY['ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.b', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.c', 'ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.b', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.a']::text[], 'The child says the sounds the theme targets (for example /l/ and /r/, /s/ and /ʃ/, /f/ and /v/, short and long vowels) so that a listener hears the right word: lorry, shop, very, ship and sheep. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","read a word list aloud","say a sentence with the target sounds"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 4, 'Use words for members of the family in sentences', ARRAY['ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.b']::text[], 'The child uses aunt, uncle, cousin, niece, nephew, grandparent and in-law for the right person and says younger or older brother, not small or big brother, in a sentence. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the right family word","fill the gap","match the word to its meaning"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 4, 'Listen to a short oral text and recall what was said', ARRAY['ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.c', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.a']::text[], 'The child listens to a short story, speech or announcement read aloud once and answers who, what, where and when questions from what was said, in the order it was said. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["answer questions on a story read aloud","retell what was heard","follow spoken instructions"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE', 'ENGL.G4.READIN.T1_EXTENSIVE_READING', 'english', 4, 'Use a dictionary: order, guide words and meaning', ARRAY['ENGL.G4.READIN.T1_EXTENSIVE_READING.a']::text[], 'Puts words in alphabetical order (using the second and third letters when the first match), uses guide words to find the page, and picks the right meaning of a word from its entry, in 8 of 10 new items.', '["alphabetical order","guide words","choose the meaning"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'ENGL.G4.READIN.T1_EXTENSIVE_READING', 'english', 4, 'Choose the right reference book', ARRAY['ENGL.G4.READIN.T1_EXTENSIVE_READING.b', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.c', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.a']::text[], 'Chooses the dictionary, junior encyclopaedia, atlas, newspaper or timetable for what the child needs to find out, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI', 'english', 4, 'Use a, an and the', ARRAY['ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.a', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.b', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.c']::text[], 'Chooses or writes a, an or the (a before a consonant sound, an before a vowel sound, the for a known or named thing, no article for things in general) and finds the one wrong article in a short note, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING', 'english', 4, 'Know what goes in each part of a form', ARRAY['ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.a']::text[], 'Says which piece of information belongs in a box of a school, clinic or library form (name, date of birth, class, address, parent contact), in 8 of 10 new items.', '["choose the correct entry","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING', 'english', 4, 'Fill in a simple form correctly', ARRAY['ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.b']::text[], 'The child writes the right detail in each box of a simple form (full names, date of birth, school, class, signature), in capital letters where asked, and leaves no required box empty. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["fill in the form","correct the form","what goes in this box"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS', 'ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 4, 'Hear the difference between words that differ by one sound', ARRAY['ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.b', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.c']::text[], 'The child hears and points to the right word in pairs that differ by one sound: ship and sheep, light and right, fan and van, thin and tin, cat and cut. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["which word did you hear","same or different","point to the picture of the word"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'ENGL.G4.READIN.T2_INTENSIVE_READING', 'english', 4, 'Answer direct questions from a text', ARRAY['ENGL.G4.READIN.T2_INTENSIVE_READING.b', 'ENGL.G4.READIN.T3_INTENSIVE_READING_CO.a', 'ENGL.G4.READIN.T3_INTENSIVE_READING_CO.b', 'ENGL.G4.READIN.T6_INTENSIVE_READING.a', 'ENGL.G4.READIN.T6_INTENSIVE_READING.b', 'ENGL.G4.READIN.T9_INTENSIVE_READING.a', 'ENGL.G4.READIN.T9_INTENSIVE_READING.b', 'ENGL.G4.READIN.T10_INTENSIVE_READING.a', 'ENGL.G4.READIN.T10_INTENSIVE_READING.b', 'ENGL.G4.READIN.T11_INTENSIVE_READING.a', 'ENGL.G4.READIN.T11_INTENSIVE_READING.b', 'ENGL.G4.READIN.T2_INTENSIVE_READING.a']::text[], 'Finds an answer that is written in the text (who, what, where, when) and says whether a statement is true, false or not stated, in 8 of 10 new items.', '["choose the answer","type a short answer","true, false or not stated"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'ENGL.G4.READIN.T2_INTENSIVE_READING', 'english', 4, 'Answer indirect questions from a text', ARRAY['ENGL.G4.READIN.T2_INTENSIVE_READING.b', 'ENGL.G4.READIN.T3_INTENSIVE_READING_CO.b', 'ENGL.G4.READIN.T6_INTENSIVE_READING.b', 'ENGL.G4.READIN.T9_INTENSIVE_READING.b', 'ENGL.G4.READIN.T10_INTENSIVE_READING.b', 'ENGL.G4.READIN.T11_INTENSIVE_READING.b']::text[], 'Works out what is not written but is shown by clues (why a person felt or did something) and does not copy a sentence, go against the text or go too far, in 8 of 10 new items.', '["choose the answer","choose what can be worked out"]'::jsonb, '["inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'ENGL.G4.READIN.T2_INTENSIVE_READING', 'english', 4, 'Use clues in the text to find a word''s meaning', ARRAY['ENGL.G4.READIN.T2_INTENSIVE_READING.b', 'ENGL.G4.READIN.T3_INTENSIVE_READING_CO.b']::text[], 'Picks the meaning of a new word from the sentences around it, and the words that give the clue, in 8 of 10 new items.', '["choose the meaning","choose the clue"]'::jsonb, '["inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS', 'english', 4, 'Make regular plurals', ARRAY['ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.a', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.b']::text[], 'Forms the plural of regular nouns (-s, -es after s, x, ch, sh, -ies after a consonant and y, -ves for knife and leaf) and does not add -s to a number-plus-noun that is already plural, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS', 'english', 4, 'Make irregular plurals', ARRAY['ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.a', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.b']::text[], 'Writes the plural of man, woman, child, foot, tooth, mouse, person, sheep and fish and does not add -s or a second plural ending, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'ENGL.G4.WRITIN.T2_CREATIVE_WRITING', 'english', 4, 'Write an open-ended composition with relevant ideas', ARRAY['ENGL.G4.WRITIN.T2_CREATIVE_WRITING.a', 'ENGL.G4.WRITIN.T2_CREATIVE_WRITING.b']::text[], 'The child writes a short composition whose ideas all keep to the topic, with a beginning, a middle and an end, and joins sentences in more ways than and then. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write about","finish the story","plan your ideas"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 4, 'Choose polite words and phrases', ARRAY['ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.b', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.d', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.e']::text[], 'Picks the polite word or phrase for a situation (asking, thanking, apologising, refusing) and does not choose a command or a rude answer, in 8 of 10 new items.', '["choose the polite words","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN', 'ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN', 'english', 4, 'Use May I, Could you and Would you like', ARRAY['ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.a', 'ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.b']::text[], 'Builds and recognises polite requests and offers (May I go out, please? Could you help me? Would you like some tea?) with the plain verb after May I and Could you, in whole sentences, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING', 'ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING', 'english', 4, 'Write legibly and neatly in print script', ARRAY['ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.a']::text[], 'The child writes print letters of the right size and shape, sitting on the line, with tall letters tall and tails below the line, and a finger space between words. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["copy the sentence neatly","write on the lines","write the words in print"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 4, 'Use first aid words', ARRAY['ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.c']::text[], 'Uses the words of first aid (bandage, wound, bruise, sprain, ambulance, first aid kit) in the right sentence, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 4, 'Say theme words with the stress on the right syllable', ARRAY['ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.b']::text[], 'The child says theme words such as BANdage, ACcident, HOSpital and AMbulance with one strong syllable in the right place, not with every syllable equally strong. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word with the strong part","clap the strong syllable","which syllable is loudest"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS', 'ENGL.G4.READIN.T4_INTENSIVE_READING_VI', 'english', 4, 'Read a notice, timetable or chart', ARRAY['ENGL.G4.READIN.T4_INTENSIVE_READING_VI.a', 'ENGL.G4.READIN.T4_INTENSIVE_READING_VI.b']::text[], 'Finds a detail in a notice, table or timetable written in words and numbers, and says what the visual is for, in 8 of 10 new items.', '["choose the answer","type a short answer"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN', 'english', 4, 'Use I, me, he, him, we, us, they and them', ARRAY['ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.a', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.b', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.c']::text[], 'Chooses the subject form before the verb and the object form after the verb or a small word, and does not repeat a noun with a pronoun (Wanjiru she is tall), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN', 'english', 4, 'Use mine, yours, hers, ours and theirs', ARRAY['ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.a', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.b']::text[], 'Writes mine, yours, his, hers, ours or theirs when no noun follows, my, your, her, our or their before a noun, and never writes your''s, her''s or our''s, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING', 'english', 4, 'Know the parts of a friendly letter', ARRAY['ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.a']::text[], 'Names and orders the parts of a friendly letter (address, date, greeting, body, closing, name) and the punctuation of the greeting and closing, in 8 of 10 new items.', '["choose the correct part","choose the correct order"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING', 'english', 4, 'Write a friendly letter in the correct format', ARRAY['ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.b']::text[], 'The child writes a friendly letter with the address and date at the top right, Dear ..., a body in paragraphs, a closing such as Your friend, and the name. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a letter to","put the letter in order","correct the letter"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING', 'english', 4, 'Write a short text message (SMS) correctly', ARRAY['ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.c']::text[], 'The child writes a short SMS that says who it is from, what it is about and anything the reader must do, in clear words with only common short forms. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which SMS is correct","write an SMS to","what is missing from this SMS"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO', 'english', 4, 'Use words about food and a balanced diet', ARRAY['ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.b']::text[], 'Uses the words of nutrition (protein, vitamins, carbohydrates, balanced diet, fibre, nutrients) in the right sentence, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO', 'english', 4, 'Say what one likes and does not like with "I like ... but I do not like ..."', ARRAY['ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.c']::text[], 'The child joins a like and a dislike about food with but and keeps the verb plain after do not: I like beans but I do not like cabbage. The design does not name the Theme 5 pattern; this one is proposed (teacher to confirm). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["complete the sentence","choose the correct sentence","join two sentences with but"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL', 'ENGL.G4.READIN.T5_EXTENSIVE_READING', 'english', 4, 'Scan a text for a detail', ARRAY['ENGL.G4.READIN.T5_EXTENSIVE_READING.c', 'ENGL.G4.READIN.T13_EXTENSIVE_READING_IN.a', 'ENGL.G4.READIN.T13_EXTENSIVE_READING_IN.b']::text[], 'Finds a number, time, price or name by looking for the key word in the question, not by reading every word, in 8 of 10 new items.', '["choose the answer","type a short answer"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING', 'ENGL.G4.READIN.T5_EXTENSIVE_READING', 'english', 4, 'Choose reading material that suits the purpose and the reader', ARRAY['ENGL.G4.READIN.T5_EXTENSIVE_READING.a']::text[], 'The child chooses a text by what it is for and how hard it is: a graded reader at the right level for practice, a recipe book to cook, an encyclopaedia for facts, not by the cover or the thickness alone. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which book would help","choose a book for","is this book right for"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING', 'ENGL.G4.READIN.T5_EXTENSIVE_READING', 'english', 4, 'Read familiar books independently and keep going', ARRAY['ENGL.G4.READIN.T5_EXTENSIVE_READING.b', 'ENGL.G4.READIN.T7_EXTENSIVE_READING_IN.a', 'ENGL.G4.READIN.T7_EXTENSIVE_READING_IN.b']::text[], 'The child reads a graded reader alone for ten minutes or more, uses the pictures and the sentence to get past a hard word, and can retell what the book was about. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["reading log","retell the book","read to the teacher"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI', 'english', 4, 'Find adjectives in a sentence', ARRAY['ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.a', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.c']::text[], 'Names the describing word that tells more about a noun (tall girl, red bus) and does not pick the noun, the verb or an adverb, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI', 'english', 4, 'Put adjectives of size and shape in order', ARRAY['ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.b']::text[], 'Puts size before shape before the noun (a big round ball) and never puts the adjective after the noun as in Kiswahili, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING', 'english', 4, 'Know the parts of a narrative composition', ARRAY['ENGL.G4.WRITIN.T5_CREATIVE_WRITING.a', 'ENGL.G4.WRITIN.T8_CREATIVE_WRITING.a']::text[], 'Says what the title, beginning, middle and end of a narrative tell (characters and setting, the problem, what happens, how it ends), in 8 of 10 new items.', '["choose the correct part","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING', 'english', 4, 'Put sentences in order to make a paragraph', ARRAY['ENGL.G4.WRITIN.T5_CREATIVE_WRITING.b', 'ENGL.G4.WRITIN.T8_CREATIVE_WRITING.b', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.b']::text[], 'Finds the topic sentence and puts four jumbled sentences in the order that makes a clear paragraph, in 8 of 10 new items.', '["choose the order","choose the topic sentence"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING', 'english', 4, 'Write a narrative composition of about 60 to 80 words', ARRAY['ENGL.G4.WRITIN.T5_CREATIVE_WRITING.c', 'ENGL.G4.WRITIN.T8_CREATIVE_WRITING.c']::text[], 'The child writes a 60 to 80 word story in the past tense with a beginning that names the characters and setting, a problem in the middle and an ending that solves it. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a story about","continue the story","write a story from the title"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 4, 'Use words about the internet, email and safety online', ARRAY['ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.c', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.b']::text[], 'Uses email, inbox, attachment, subject, password, website, search and download in the right sentence, and tells safe online habits from unsafe ones, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 4, 'Use falling and rising intonation for questions and statements', ARRAY['ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.b']::text[], 'The child lets the voice fall at the end of a statement and a WH question (Where do you live?) and rise at the end of a yes or no question (Do you live in Nakuru?). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["does the voice go up or down","say the question","say it as a statement and as a question"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE', 'english', 4, 'Use many, much, few and little', ARRAY['ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.a', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.b']::text[], 'Uses many and few with things you can count and much and little with things you cannot count, in statements and questions, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE', 'english', 4, 'Use some, any, a lot of and enough', ARRAY['ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.a', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.b', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.c']::text[], 'Uses some in positive sentences, any in questions and negatives, a lot of and enough before the noun, and does not put enough after the noun, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING', 'english', 4, 'Put the pictures of a story in order', ARRAY['ENGL.G4.WRITIN.T6_CREATIVE_WRITING.a']::text[], 'Orders four pictures, given in words, so that the story makes sense, and picks the sentence that tells one picture in the past tense, in 8 of 10 new items.', '["choose the order","choose the sentence"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING', 'english', 4, 'Write a composition of about 60 to 80 words from a series of pictures', ARRAY['ENGL.G4.WRITIN.T6_CREATIVE_WRITING.b']::text[], 'The child writes one or two linked sentences for each picture in order, in the past tense, so the pictures become one story with a title. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write the story the pictures tell","one sentence for each picture","add a title"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO', 'english', 4, 'Use the past tense in a dialogue', ARRAY['ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.c']::text[], 'Uses the regular (-ed) and irregular (went, ate, saw) past forms when the time is past, and uses the present forms for habits and facts, in short dialogues, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO', 'english', 4, 'Take turns in a two-way conversation', ARRAY['ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.b']::text[], 'The child listens until the speaker finishes, answers what was asked, adds a little and hands the turn back with a question, in a conversation of four or more turns. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["role play a conversation","keep the conversation going","what should you say next"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS', 'english', 4, 'Use am, is and are with -ing', ARRAY['ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.a', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.b']::text[], 'Writes am, is or are plus the -ing verb for an action happening now, with the right form of be and the right spelling of -ing, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS', 'english', 4, 'Use was and were with -ing', ARRAY['ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.a', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.b']::text[], 'Writes was or were plus the -ing verb for an action that was going on at a time in the past, and does not use is or are, a past form or a bare verb, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING', 'english', 4, 'Use capital letters and full stops', ARRAY['ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.a', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.b', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.c']::text[], 'Starts a sentence and every name with a capital letter, writes I as a capital, and ends a statement with a full stop, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS', 'ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 4, 'Use words about the farm', ARRAY['ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.c']::text[], 'Uses the words of the farm (harvest, seedlings, fertiliser, livestock, plough, weeding) in the right sentence, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY', 'ENGL.G4.READIN.T8_READING_FLUENCY', 'english', 4, 'Read a text of about 300 words accurately, at the right speed and with expression', ARRAY['ENGL.G4.READIN.T8_READING_FLUENCY.a', 'ENGL.G4.READIN.T8_READING_FLUENCY.b', 'ENGL.G4.READIN.T12_1_INTENSIVE_READING.b']::text[], 'The child reads a 300-word text aloud in phrases, pauses at full stops and commas, changes the voice for questions and speech, and reads most words right the first time. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read a paragraph with expression","read a dialogue in parts"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS', 'ENGL.G4.LANGUA.T8_WORD_CLASSES', 'english', 4, 'Write short forms of verbs', ARRAY['ENGL.G4.LANGUA.T8_WORD_CLASSES.a']::text[], 'Writes the short form (don''t, isn''t, can''t, I''m, she''s, we''ll) with the apostrophe where the letter is missing, and tells it''s (it is) from its (belonging to it), in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS', 'ENGL.G4.LANGUA.T8_WORD_CLASSES', 'english', 4, 'Turn a positive statement into a negative one', ARRAY['ENGL.G4.LANGUA.T8_WORD_CLASSES.b', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.c']::text[], 'Makes a negative with do not, does not, did not, is not or cannot, keeps the verb plain after does and did, and does not use two negatives together, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY', 'ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO', 'english', 4, 'Speak on a topic fluently, at a good speed and without long pauses', ARRAY['ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.a', 'ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.a']::text[], 'The child talks for about a minute on a familiar topic in full sentences, at a speed listeners can follow, with few fillers (eeh, aah) and no long stops to search for words. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["talk for one minute on a topic","tell the class about","answer and say more"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS', 'ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS', 'english', 4, 'Use adverbs of manner, time and place', ARRAY['ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.a', 'ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.b']::text[], 'Says whether an adverb tells how, when or where, uses the adverb form (quickly, well) after the verb, and does not use an adjective where the adverb belongs, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall","rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS', 'ENGL.G4.WRITIN.T9_PUNCTUATION', 'english', 4, 'Use commas in a list', ARRAY['ENGL.G4.WRITIN.T9_PUNCTUATION.a', 'ENGL.G4.WRITIN.T9_PUNCTUATION.b', 'ENGL.G4.WRITIN.T9_PUNCTUATION.c']::text[], 'Puts a comma between the items of a list (with and before the last), not after the last item and not between a person and what the person does, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS', 'ENGL.G4.WRITIN.T9_PUNCTUATION', 'english', 4, 'Use the question mark', ARRAY['ENGL.G4.WRITIN.T9_PUNCTUATION.a', 'ENGL.G4.WRITIN.T9_PUNCTUATION.b']::text[], 'Ends an asking sentence with a question mark, and a telling sentence with a full stop, even when the sentence has a question word in it, in 8 of 10 new items.', '["choose the correct sentence","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 4, 'Use words about hygiene and sanitation', ARRAY['ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.d']::text[], 'Uses the words of hygiene (germs, sanitiser, latrine, rubbish, disinfect, drainage) in the right sentence, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 4, 'Interrupt a speaker politely', ARRAY['ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.c']::text[], 'The child waits for a pause, then uses Excuse me, may I ... or Sorry to interrupt, but ... and lets the speaker finish the point. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the polite way","what would you say","spot the rude interruption"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI', 'english', 4, 'Join ideas with and, but, because, so and or', ARRAY['ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.a', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.c', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.b']::text[], 'Chooses the joining word that matches the meaning of the two parts (addition, contrast, reason, result, choice) and uses one joining word between two ideas, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING', 'english', 4, 'Know the parts of a descriptive composition', ARRAY['ENGL.G4.WRITIN.T10_CREATIVE_WRITING.a']::text[], 'Says what the introduction, the description (using the senses) and the conclusion of a descriptive composition do, and tells a description from a story, in 8 of 10 new items.', '["choose the correct part","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING', 'english', 4, 'Write a descriptive composition of about 80 to 100 words', ARRAY['ENGL.G4.WRITIN.T10_CREATIVE_WRITING.c']::text[], 'The child describes one person, place or thing in 80 to 100 words: what it looks, sounds, smells and feels like, with an introduction and a conclusion, in the present tense. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["describe a place","describe a person","use your senses"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO', 'english', 4, 'Use words about sports and games', ARRAY['ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.b']::text[], 'Uses the words of sport (referee, goalkeeper, tournament, trophy, opponent, whistle) in the right sentence, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO', 'english', 4, 'Read and use gestures, faces and tone of voice', ARRAY['ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.d', 'ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.b']::text[], 'The child says what a gesture, facial expression or tone of voice shows (a nod agrees, a frown is unhappy or confused, a finger on the lips asks for quiet) and uses fitting gestures when speaking. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what does this face or gesture show","how is the speaker feeling","which gesture fits"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS', 'english', 4, 'Ask questions with who, what, where, when, why, how and whose', ARRAY['ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.a', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.b', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.c']::text[], 'Chooses the question word that fits the answer given, puts the helping verb before the subject, and does not write who''s for whose, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING', 'english', 4, 'Spell commonly misspelt words', ARRAY['ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.a', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.b', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.c']::text[], 'Spells words like because, friend, beautiful, believe, library, Wednesday and tomorrow correctly, from the first letters to the last, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS', 'ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO', 'english', 4, 'Use words about a clean environment', ARRAY['ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.c']::text[], 'Uses the words of the environment (pollution, recycle, litter, compost, conserve, habitat) in the right sentence, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS', 'ENGL.G4.READIN.T12_1_INTENSIVE_READING', 'english', 4, 'Know proverbs and what they teach', ARRAY['ENGL.G4.READIN.T12_1_INTENSIVE_READING.a', 'ENGL.G4.READIN.T12_1_INTENSIVE_READING.c']::text[], 'Says the lesson of a common proverb and finishes a proverb with its right word, and does not read it as only about the animals or things in it, in 8 of 10 new items.', '["choose the meaning","finish the proverb"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS', 'english', 4, 'Use have and has with the past participle', ARRAY['ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.a', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.b']::text[], 'Writes have or has plus the past participle (have eaten, has gone) for an action that has just finished or still matters, and does not use it with yesterday or last week, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS', 'english', 4, 'Use had with the past participle', ARRAY['ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.a', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.b']::text[], 'Writes had plus the past participle for the action that happened first when two past actions are told, and keeps the order of the two events right, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["rule"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION', 'english', 4, 'Know the parts of a diary entry', ARRAY['ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.a']::text[], 'Says what a diary entry has (date, a greeting to the diary, what happened and how the writer felt, in the first person and the past tense) and what it does not have, in 8 of 10 new items.', '["choose the correct part","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION', 'english', 4, 'Write a diary entry in the right format', ARRAY['ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.b']::text[], 'The child writes a dated diary entry (Dear Diary optional) in the first person and the past tense about the day, saying how he or she felt. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a diary entry for today","correct the diary entry","add the missing parts"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO', 'english', 4, 'Use words about money', ARRAY['ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.d']::text[], 'Uses the words of money (savings, budget, price, change, loan, borrow, earn) in the right sentence and does not swap earn with save or borrow with lend, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO', 'english', 4, 'Find the silent letter in a word', ARRAY['ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.b']::text[], 'Names the silent letter in words like knife, write, lamb, listen, hour and walk, and does not pick the letter beside it, in 8 of 10 new items.', '["choose the letter","type the letter","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO', 'english', 4, 'Use the pattern "very ... but ..."', ARRAY['ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.c']::text[], 'The child joins a strong quality with a contrasting one: The shoes are very nice but they are expensive. Very goes before a plain adjective, and but joins two ideas that pull different ways. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["complete the sentence","choose the correct sentence","join the two ideas"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI', 'english', 4, 'Use in, on, under, behind, between and next to', ARRAY['ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.a', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.b']::text[], 'Chooses the preposition that says where a thing is (in, on, under, behind, in front of, between, next to) from the picture in words, in 8 of 10 new sentences, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI', 'english', 4, 'Use to, into, out of, across, through and along', ARRAY['ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.a', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.b']::text[], 'Chooses the preposition that says where something moves (into the room, out of the house, across the road, through the gate), and does not write to home or go at school, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS', 'ENGL.G4.WRITIN.T13_SPELLING', 'english', 4, 'Spell words with double consonants', ARRAY['ENGL.G4.WRITIN.T13_SPELLING.a', 'ENGL.G4.WRITIN.T13_SPELLING.b', 'ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.b', 'ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.c', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.c', 'ENGL.G4.WRITIN.T13_SPELLING.c']::text[], 'Spells words with a double consonant (summer, coffee, address, rabbit, letter) and does not double a letter that has only one, in 8 of 10 new items.', '["choose the correct word","fill the gap","spot the mistake"]'::jsonb, '["recall"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'skill', 'essential', 'Grade 3 pronounced words with target letter-sounds. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
