INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M4_PS_L_R', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Swaps /l/ and /r/.', '{"question":"Say: The lorry is red.","wrong_answer":"The rorry is led.","correct_answer":"The lorry is red."}'::jsonb, 'Several Kenyan home languages do not keep /l/ and /r/ apart, so one is used for both.', 'Offer "The rorry is led." beside "The lorry is red." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue tip up behind the teeth for /l/; tongue curled back, not touching, for /r/.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M4_PS_SH_S', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /s/ for /ʃ/ (sh).', '{"question":"Say: shop","wrong_answer":"sop","correct_answer":"shop"}'::jsonb, 'The home language may have no /ʃ/, so the nearest sound /s/ is used.', 'Offer "sop" beside "shop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Round the lips and push them forward for sh: shhh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M4_PS_CH_SH', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /ʃ/ (sh) for /tʃ/ (ch).', '{"question":"Say: chair","wrong_answer":"shair","correct_answer":"chair"}'::jsonb, 'A home language with sh but no ch, or the reverse, carries over.', 'Offer "shair" beside "chair" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ch starts with a stop: t then sh, as in t-shair, chair.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M4_PS_V_F', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says /f/ for /v/.', '{"question":"Say: very","wrong_answer":"fery","correct_answer":"very"}'::jsonb, 'The voiced /v/ is missing in some home languages, so the voiceless /f/ is used.', 'Offer "fery" beside "very" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Same teeth on lip as f, but switch the voice on: feel the buzz in the throat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M4_PS_EXTRA_VOWEL', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Adds a vowel between consonants or at the end of a word.', '{"question":"Say: film","wrong_answer":"filim","correct_answer":"film"}'::jsonb, 'Bantu languages build syllables that end in a vowel, so a vowel is slipped into English consonant clusters.', 'Offer "filim" beside "film" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold the two consonants together with no sound between: f-i-lm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS.M4_PS_SHIP_SHEEP', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_SOUNDS', 'Says the short /ɪ/ and the long /iː/ the same.', '{"question":"Say: ship, sheep","wrong_answer":"ship and ship sound the same","correct_answer":"ship (short), sheep (long)"}'::jsonb, 'Home languages have one i sound, so the length difference is not heard.', 'Offer "ship and ship sound the same" beside "ship (short), sheep (long)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short i is quick and relaxed; long ee is longer, lips spread in a smile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB.M4_FV_COUSIN_BROTHER', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB', 'Calls a cousin a brother or sister.', '{"question":"My uncle''s son is my ...","wrong_answer":"brother","correct_answer":"cousin"}'::jsonb, 'In many Kenyan families a cousin is called brother or sister, and the home word is carried into English.', 'Offer "brother" beside "cousin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Your uncle''s or aunt''s child is your cousin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB.M4_FV_SMALL_BROTHER', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB', 'Says small brother or big sister for younger or older.', '{"question":"Juma was born after me. He is my ...","wrong_answer":"small brother","correct_answer":"younger brother"}'::jsonb, 'A direct translation from Kiswahili (kaka mdogo) and common Kenyan English.', 'Offer "small brother" beside "younger brother" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use younger and older for age; small and big are for size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB.M4_FV_NIECE_NEPHEW', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB', 'Swaps niece and nephew.', '{"question":"My sister''s daughter is my ...","wrong_answer":"nephew","correct_answer":"niece"}'::jsonb, 'The two words are learnt together and sound alike.', 'Offer "nephew" beside "niece" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Niece is a girl, nephew is a boy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB.M4_FV_AUNT_UNCLE', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.FAMILY_VOCAB', 'Calls a father''s sister an uncle or a mother''s brother an aunt.', '{"question":"My mother''s brother is my ...","wrong_answer":"aunt","correct_answer":"uncle"}'::jsonb, 'The child thinks of whose side the person is on, not whether the person is a man or a woman.', 'Offer "aunt" beside "uncle" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'An uncle is a man, an aunt is a woman, on either side of the family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE.M4_LA_LAST_HEARD', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE', 'Remembers only the last thing heard.', '{"question":"Teacher reads: \"Amina fed the goats, then went to the river.\" What did Amina do first?","wrong_answer":"went to the river","correct_answer":"fed the goats"}'::jsonb, 'The end of the text is freshest, and the order is not held in mind.', 'Offer "went to the river" beside "fed the goats" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold up a finger for each event as you listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE.M4_LA_OWN_DETAIL', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE', 'Adds a detail the speaker did not say.', '{"question":"Teacher reads: \"Baraka took the bus to Kisumu.\" How did Baraka travel to Kisumu?","wrong_answer":"by matatu with his mother","correct_answer":"by bus"}'::jsonb, 'The child fills gaps from his or her own life.', 'Offer "by matatu with his mother" beside "by bus" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say only what the speaker said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE.M4_LA_WHO_SWAP', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE', 'Mixes up who did what.', '{"question":"Teacher reads: \"Wanjiru helped Otieno carry the water.\" Who carried the water with help?","wrong_answer":"Wanjiru","correct_answer":"Otieno"}'::jsonb, 'Two names close together; the child keeps the first name heard.', 'Offer "Wanjiru" beside "Otieno" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask who did the action and who received it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE.M4_LA_KEYWORD_GRAB', 'ENGL.G4.LISTEN.T1_PRONUNCIATION_AND_VO.LISTEN_ATTENTIVE', 'Answers with a word heard in the text that does not answer the question.', '{"question":"Teacher reads: \"The market opens at seven on Tuesday.\" When does the market open?","wrong_answer":"Tuesday market","correct_answer":"at seven on Tuesday"}'::jsonb, 'The child grabs a familiar word instead of listening for the question word.', 'Offer "Tuesday market" beside "at seven on Tuesday" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the question word: when wants a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE.M_DIC_ALPHA_FIRST_LETTER', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE', 'Orders words by the first letter only.', '{"question":"Order: bat, bag, ball","wrong_answer":"bat, bag, ball","correct_answer":"bag, ball, bat"}'::jsonb, 'Stops comparing after the first letter.', 'A question like "Order: bat, bag, ball" with "bat, bag, ball" among the options.', 'Have the child say both forms aloud and say why one fits: "bag, ball, bat", not "bat, bag, ball".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE.M_DIC_GUIDE_WORDS', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE', 'Does not use the guide words to find the page.', '{"question":"Guide words \"cat\" and \"cow\": is \"cup\" on this page?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Does not know guide words are the first and last words on the page.', 'A question like "Guide words "cat" and "cow": is "cup" on this page?" with "Yes" among the options.', 'Have the child say both forms aloud and say why one fits: "No", not "Yes".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE.M_DIC_WRONG_MEANING', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE', 'Picks a meaning that fits another sense of the word.', '{"question":"sprint","wrong_answer":"a long walk","correct_answer":"a very fast run for a short distance"}'::jsonb, 'Chooses the first meaning that sounds familiar.', 'A question like "sprint" with "a long walk" among the options.', 'Have the child say both forms aloud and say why one fits: "a very fast run for a short distance", not "a long walk".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_DICTIONARY_FOR_FACTS', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Uses a dictionary to find facts about a topic.', '{"question":"You want facts about elephants.","wrong_answer":"a dictionary","correct_answer":"a junior encyclopaedia"}'::jsonb, 'Thinks every reference book does the same job.', 'A question like "You want facts about elephants." with "a dictionary" among the options.', 'Have the child say both forms aloud and say why one fits: "a junior encyclopaedia", not "a dictionary".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_ATLAS_FOR_WORDS', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Uses an atlas to find the meaning of a word.', '{"question":"You want to find a map of Kenya.","wrong_answer":"a dictionary","correct_answer":"an atlas"}'::jsonb, 'Does not link the book to what it holds.', 'A question like "You want to find a map of Kenya." with "a dictionary" among the options.', 'Have the child say both forms aloud and say why one fits: "an atlas", not "a dictionary".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_STORY_FOR_FACTS', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Uses a story book to look up information.', '{"question":"You want to know a bus time.","wrong_answer":"a story book","correct_answer":"a timetable"}'::jsonb, 'Thinks a book is good for any need.', 'A question like "You want to know a bus time." with "a story book" among the options.', 'Have the child say both forms aloud and say why one fits: "a timetable", not "a story book".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS.M_REF_NEWSPAPER_OLD', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.REFERENCE_MATERIALS', 'Uses a newspaper for facts that do not change.', '{"question":"You want today''s news.","wrong_answer":"a dictionary","correct_answer":"a newspaper"}'::jsonb, 'Does not think about when the information is needed.', 'A question like "You want today''s news." with "a dictionary" among the options.', 'Have the child say both forms aloud and say why one fits: "a newspaper", not "a dictionary".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE.M4_DIC_FIRST_MEANING', 'ENGL.G4.READIN.T1_EXTENSIVE_READING.DICTIONARY_USE', 'Always takes the first meaning listed, even when another fits the sentence.', '{"question":"\"The bank of the river was muddy.\" Bank means ...","wrong_answer":"a place that keeps money","correct_answer":"the land at the side of a river"}'::jsonb, 'The child stops at the first numbered meaning.', 'Offer "a place that keeps money" beside "the land at the side of a river" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read all the meanings and choose the one that fits the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES.M_ART_A_BEFORE_VOWEL', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'Writes a before a word that starts with a vowel sound.', '{"question":"She ate ___ orange.","wrong_answer":"a","correct_answer":"an"}'::jsonb, 'Learns "a" as the only small word and does not listen to the first sound of the next word.', 'A question like "She ate ___ orange." with "a" among the options.', 'Have the child say both forms aloud and say why one fits: "an", not "a".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES.M_ART_AN_BEFORE_CONSONANT', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'Writes an before a word that starts with a consonant sound.', '{"question":"I bought ___ book.","wrong_answer":"an","correct_answer":"a"}'::jsonb, 'Over-corrects after learning that "an" goes before vowels.', 'A question like "I bought ___ book." with "an" among the options.', 'Have the child say both forms aloud and say why one fits: "a", not "an".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES.M_ART_SOUND_NOT_LETTER', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'Chooses a or an by the first letter, not the first sound.', '{"question":"We waited for ___ hour.","wrong_answer":"a","correct_answer":"an"}'::jsonb, 'Looks at the letter h (or u) instead of listening to the sound.', 'A question like "We waited for ___ hour." with "a" among the options.', 'Have the child say both forms aloud and say why one fits: "an", not "a".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES.M_ART_THE_FIRST_MENTION', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'Uses the for something that has not been mentioned before.', '{"question":"Mama gave me ___ apple.","wrong_answer":"the","correct_answer":"an"}'::jsonb, 'Thinks the is the main article.', 'A question like "Mama gave me ___ apple." with "the" among the options.', 'Have the child say both forms aloud and say why one fits: "an", not "the".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES.M_ART_A_FOR_KNOWN', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'Uses a or an for something that is known or the only one.', '{"question":"We feel the heat of ___ sun.","wrong_answer":"a","correct_answer":"the"}'::jsonb, 'Does not see that there is only one of it.', 'A question like "We feel the heat of ___ sun." with "a" among the options.', 'Have the child say both forms aloud and say why one fits: "the", not "a".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES.M_ART_OMITTED', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'Leaves out the article before a singular noun.', '{"question":"Kamau has ___ new bicycle.","wrong_answer":"no article","correct_answer":"a"}'::jsonb, 'Kiswahili has no articles, so the small word is not heard as needed.', 'A question like "Kamau has ___ new bicycle." with "no article" among the options.', 'Have the child say both forms aloud and say why one fits: "a", not "no article".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES.M_ART_THE_GENERAL', 'ENGL.G4.LANGUA.T1_WORD_CLASSES_DETERMI.ARTICLES', 'Uses the for things in general, or uses a with a plural.', '{"question":"___ lions are strong animals.","wrong_answer":"The","correct_answer":"no article (Lions are strong animals.)"}'::jsonb, 'Believes "the" is needed before every noun.', 'A question like "___ lions are strong animals." with "The" among the options.', 'Have the child say both forms aloud and say why one fits: "no article (Lions are strong animals.)", not "The".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION.M_FRM_DETAIL_MIX', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION', 'Writes the wrong detail in a box.', '{"question":"Date of birth: ","wrong_answer":"Nairobi","correct_answer":"14th March 2016"}'::jsonb, 'Does not read what the box asks for.', 'A question like "Date of birth: " with "Nairobi" among the options.', 'Have the child say both forms aloud and say why one fits: "14th March 2016", not "Nairobi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION.M_FRM_AGE_FOR_DOB', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION', 'Writes the age in the date of birth box.', '{"question":"Date of birth: ","wrong_answer":"9 years","correct_answer":"14th March 2016"}'::jsonb, 'Confuses age with date of birth.', 'A question like "Date of birth: " with "9 years" among the options.', 'Have the child say both forms aloud and say why one fits: "14th March 2016", not "9 years".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION.M_FRM_CONTACT_FOR_ADDRESS', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION', 'Writes a phone number in the address box.', '{"question":"Home address: ","wrong_answer":"0712 345 678","correct_answer":"P.O. Box 12, Kisumu"}'::jsonb, 'Does not tell address from contact.', 'A question like "Home address: " with "0712 345 678" among the options.', 'Have the child say both forms aloud and say why one fits: "P.O. Box 12, Kisumu", not "0712 345 678".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION.M_FRM_NAME_PART', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FORM_INFORMATION', 'Writes only one name in the full names box.', '{"question":"Full names: ","wrong_answer":"Wanjiru","correct_answer":"Wanjiru Kamau Njeri"}'::jsonb, 'Thinks the first name is enough.', 'A question like "Full names: " with "Wanjiru" among the options.', 'Have the child say both forms aloud and say why one fits: "Wanjiru Kamau Njeri", not "Wanjiru".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM.M4_FF_LOWER_CASE', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM', 'Writes in small letters where the form asks for capitals.', '{"question":"NAME (IN CAPITALS): ...","wrong_answer":"amina wekesa","correct_answer":"AMINA WEKESA"}'::jsonb, 'The instruction in brackets is not read.', 'Offer "amina wekesa" beside "AMINA WEKESA" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the instruction in brackets before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM.M4_FF_EMPTY_BOX', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM', 'Leaves a required box empty.', '{"question":"A form has Class: [ ]. What do you write?","wrong_answer":"nothing","correct_answer":"Grade 4 East"}'::jsonb, 'The child skips boxes he or she is unsure of.', 'Offer "nothing" beside "Grade 4 East" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fill every box; write N/A only if it does not apply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM.M4_FF_SIGN_AS_NAME', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM', 'Writes the full name in print in the signature box.', '{"question":"What goes in the Signature box?","wrong_answer":"AMINA WEKESA (printed)","correct_answer":"Amina''s own signature"}'::jsonb, 'The child does not know what a signature is.', 'Offer "AMINA WEKESA (printed)" beside "Amina''s own signature" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A signature is your own special way of writing your name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM.M4_FF_OUTSIDE_BOX', 'ENGL.G4.WRITIN.T1_FUNCTIONAL_WRITING.FILL_FORM', 'Writes outside the box or over the lines.', '{"question":"The box for School is small. How do you write?","wrong_answer":"big letters over the lines","correct_answer":"small, neat letters inside the box"}'::jsonb, 'The child writes as in an exercise book.', 'Offer "big letters over the lines" beside "small, neat letters inside the box" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep your writing inside the box.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS.M4_DS_SHIP_SHEEP', 'ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS', 'Cannot hear the short and long i apart.', '{"question":"Teacher says \"sheep\". Which picture: a ship or a sheep?","wrong_answer":"ship","correct_answer":"sheep"}'::jsonb, 'One i sound in the home language.', 'Offer "ship" beside "sheep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the long sound: sheep is longer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS.M4_DS_L_R', 'ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS', 'Cannot hear /l/ and /r/ apart.', '{"question":"Teacher says \"right\". Light or right?","wrong_answer":"light","correct_answer":"right"}'::jsonb, 'L and r are one sound in some home languages.', 'Offer "light" beside "right" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Watch the tongue: up for l, curled back for r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS.M4_DS_F_V', 'ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS', 'Cannot hear /f/ and /v/ apart.', '{"question":"Teacher says \"van\". Fan or van?","wrong_answer":"fan","correct_answer":"van"}'::jsonb, 'No voiced /v/ in the home language.', 'Offer "fan" beside "van" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put a hand on your throat: v buzzes, f does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS.M4_DS_TH_T', 'ENGL.G4.LISTEN.T2_PRONUNCIATION_AND_VO.DISCRIMINATE_SOUNDS', 'Hears /θ/ (th) as /t/ or /s/.', '{"question":"Teacher says \"thin\". Thin, tin or sin?","wrong_answer":"tin","correct_answer":"thin"}'::jsonb, 'Th is rare in home languages and is heard as the nearest sound.', 'Offer "tin" beside "thin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Th has the tongue between the teeth: look at the speaker''s mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_NEARBY_DETAIL', 'ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Picks a detail that sits near the answer in the text.', '{"question":"What was tied inside the bag?","wrong_answer":"sand","correct_answer":"rags"}'::jsonb, 'Reads fast and picks a nearby word.', 'A question like "What was tied inside the bag?" with "sand" among the options.', 'Have the child say both forms aloud and say why one fits: "rags", not "sand".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_OUTSIDE_KNOWLEDGE', 'ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Answers from what he or she already knows.', '{"question":"How did they travel?","wrong_answer":"by bus","correct_answer":"by boda boda"}'::jsonb, 'Does not go back to the text.', 'A question like "How did they travel?" with "by bus" among the options.', 'Have the child say both forms aloud and say why one fits: "by boda boda", not "by bus".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_MISSES_STATED', 'ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says not stated when the text does say it.', '{"question":"True, false or not stated: Achieng set tomatoes in heaps.","wrong_answer":"Not stated","correct_answer":"True"}'::jsonb, 'Does not find the sentence.', 'A question like "True, false or not stated: Achieng set tomatoes in heaps." with "Not stated" among the options.', 'Have the child say both forms aloud and say why one fits: "True", not "Not stated".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_FALSE_AS_TRUE', 'ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says true when the text says something different.', '{"question":"The market was in Nakuru.","wrong_answer":"True","correct_answer":"False"}'::jsonb, 'Reads for the topic, not the exact detail.', 'A question like "The market was in Nakuru." with "True" among the options.', 'Have the child say both forms aloud and say why one fits: "False", not "True".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_FALSE_AS_NOT_STATED', 'ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says not stated when the text says something different.', '{"question":"The market was in Nakuru.","wrong_answer":"Not stated","correct_answer":"False"}'::jsonb, 'Does not tell going against the text from saying nothing.', 'A question like "The market was in Nakuru." with "Not stated" among the options.', 'Have the child say both forms aloud and say why one fits: "False", not "Not stated".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_NOT_STATED_AS_TRUE', 'ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Says true or false when the text does not say.', '{"question":"Kamau scored a goal.","wrong_answer":"True","correct_answer":"Not stated"}'::jsonb, 'Fills in what seems likely.', 'A question like "Kamau scored a goal." with "True" among the options.', 'Have the child say both forms aloud and say why one fits: "Not stated", not "True".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS.M_FACT_WRONG_WHO', 'ENGL.G4.READIN.T2_INTENSIVE_READING.FACTUAL_QUESTIONS', 'Picks the wrong person or place for who or where.', '{"question":"Who helped Kamau?","wrong_answer":"his teacher","correct_answer":"his grandmother"}'::jsonb, 'Picks the first name seen.', 'A question like "Who helped Kamau?" with "his teacher" among the options.', 'Have the child say both forms aloud and say why one fits: "his grandmother", not "his teacher".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M_INFER_REPEATS_TEXT', 'ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Copies a sentence from the text as the answer.', '{"question":"Why did Mother nod proudly?","wrong_answer":"The woman wore a green dress.","correct_answer":"Achieng counted carefully and gave the right change."}'::jsonb, 'Does not see that the answer is not written.', 'A question like "Why did Mother nod proudly?" with "The woman wore a green dress." among the options.', 'Have the child say both forms aloud and say why one fits: "Achieng counted carefully and gave the right change.", not "The woman wore a green dress.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M_INFER_CONTRADICTS', 'ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Picks an answer that goes against the text.', '{"question":"Why was Kamau sad?","wrong_answer":"The school was closed.","correct_answer":"He loved football and the ball burst."}'::jsonb, 'Does not check the answer against the text.', 'A question like "Why was Kamau sad?" with "The school was closed." among the options.', 'Have the child say both forms aloud and say why one fits: "He loved football and the ball burst.", not "The school was closed.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M_INFER_OVERREACH', 'ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Picks an answer that goes too far.', '{"question":"What can you tell about the grandmother?","wrong_answer":"She is the richest woman in town.","correct_answer":"She is kind and clever."}'::jsonb, 'Adds facts that the text does not support.', 'A question like "What can you tell about the grandmother?" with "She is the richest woman in town." among the options.', 'Have the child say both forms aloud and say why one fits: "She is kind and clever.", not "She is the richest woman in town.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_LOOKS_LIKE', 'ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Picks a meaning that looks like the word.', '{"question":"burst","wrong_answer":"rolled away","correct_answer":"broke open"}'::jsonb, 'Guesses from the look of the word.', 'A question like "burst" with "rolled away" among the options.', 'Have the child say both forms aloud and say why one fits: "broke open", not "rolled away".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_COMMON_MEANING', 'ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Picks a common meaning that does not fit.', '{"question":"heaps","wrong_answer":"big baskets","correct_answer":"small piles"}'::jsonb, 'Uses a known meaning without testing it.', 'A question like "heaps" with "big baskets" among the options.', 'Have the child say both forms aloud and say why one fits: "small piles", not "big baskets".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_OPPOSITE', 'ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Picks the opposite meaning.', '{"question":"ancient","wrong_answer":"very new","correct_answer":"very old"}'::jsonb, 'Does not read the clue.', 'A question like "ancient" with "very new" among the options.', 'Have the child say both forms aloud and say why one fits: "very old", not "very new".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES.M_CTX_WRONG_CLUE', 'ENGL.G4.READIN.T2_INTENSIVE_READING.CONTEXT_CLUES', 'Picks a group of words that does not explain the word.', '{"question":"Which words help you?","wrong_answer":"in Nyeri","correct_answer":"the school had no money for a new one"}'::jsonb, 'Picks any phrase near the word.', 'A question like "Which words help you?" with "in Nyeri" among the options.', 'Have the child say both forms aloud and say why one fits: "the school had no money for a new one", not "in Nyeri".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS.M4_INFER_FEELING_GUESS', 'ENGL.G4.READIN.T2_INTENSIVE_READING.INFERENCE_QUESTIONS', 'Names a feeling with no clue in the text to support it.', '{"question":"\"Juma threw his bag down and slammed the door.\" How did Juma feel?","wrong_answer":"tired","correct_answer":"angry"}'::jsonb, 'The child picks a feeling from his or her own day.', 'Offer "tired" beside "angry" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the clue: throwing and slamming show anger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR.M_PLR_NO_ES', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR', 'Adds only -s to a word that ends in s, x, ch or sh.', '{"question":"two ___ (box)","wrong_answer":"boxs","correct_answer":"boxes"}'::jsonb, 'Uses the plain -s rule for every word.', 'A question like "two ___ (box)" with "boxs" among the options.', 'Have the child say both forms aloud and say why one fits: "boxes", not "boxs".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR.M_PLR_Y_TO_S', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR', 'Adds -s to a word that ends in a consonant and y.', '{"question":"three ___ (baby)","wrong_answer":"babys","correct_answer":"babies"}'::jsonb, 'Does not change y to i before the ending.', 'A question like "three ___ (baby)" with "babys" among the options.', 'Have the child say both forms aloud and say why one fits: "babies", not "babys".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR.M_PLR_VOWEL_Y_IES', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR', 'Changes y to -ies after a vowel.', '{"question":"two ___ (monkey)","wrong_answer":"monkies","correct_answer":"monkeys"}'::jsonb, 'Over-corrects after learning baby, babies.', 'A question like "two ___ (monkey)" with "monkies" among the options.', 'Have the child say both forms aloud and say why one fits: "monkeys", not "monkies".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR.M_PLR_F_NO_VES', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR', 'Adds -s to knife, leaf, wife and loaf.', '{"question":"two ___ (leaf)","wrong_answer":"leafs","correct_answer":"leaves"}'::jsonb, 'Does not know the f to v change.', 'A question like "two ___ (leaf)" with "leafs" among the options.', 'Have the child say both forms aloud and say why one fits: "leaves", not "leafs".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR.M_PLR_SINGULAR_AFTER_NUMBER', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_REGULAR', 'Keeps the noun singular after a number.', '{"question":"I have four ___.","wrong_answer":"book","correct_answer":"books"}'::jsonb, 'Kiswahili does not change the noun after a number in the same way.', 'A question like "I have four ___." with "book" among the options.', 'Have the child say both forms aloud and say why one fits: "books", not "book".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR.M_PLI_ADD_S', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR', 'Adds -s to an irregular noun.', '{"question":"three ___ (child)","wrong_answer":"childs","correct_answer":"children"}'::jsonb, 'Uses the regular rule for every noun.', 'A question like "three ___ (child)" with "childs" among the options.', 'Have the child say both forms aloud and say why one fits: "children", not "childs".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR.M_PLI_DOUBLE_PLURAL', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR', 'Adds -s to a plural that is already plural.', '{"question":"Many ___ were playing. (child)","wrong_answer":"childrens","correct_answer":"children"}'::jsonb, 'Knows the word changes but adds -s from habit.', 'A question like "Many ___ were playing. (child)" with "childrens" among the options.', 'Have the child say both forms aloud and say why one fits: "children", not "childrens".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR.M_PLI_FOOT_TOOTH', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR', 'Writes tooths, mouses or gooses.', '{"question":"two ___ (tooth)","wrong_answer":"tooths","correct_answer":"teeth"}'::jsonb, 'Does not know the vowel change.', 'A question like "two ___ (tooth)" with "tooths" among the options.', 'Have the child say both forms aloud and say why one fits: "teeth", not "tooths".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR.M_PLI_SAME_FORM_S', 'ENGL.G4.LANGUA.T2_WORD_CLASSES_NOUNS.PLURALS_IRREGULAR', 'Adds -s to sheep or fish.', '{"question":"ten ___ (sheep)","wrong_answer":"sheeps","correct_answer":"sheep"}'::jsonb, 'Treats every animal word as regular.', 'A question like "ten ___ (sheep)" with "sheeps" among the options.', 'Have the child say both forms aloud and say why one fits: "sheep", not "sheeps".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M4_OC_OFF_TOPIC', 'ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Writes ideas that leave the topic.', '{"question":"Topic: My best day. Which sentence fits?","wrong_answer":"Cows give us milk.","correct_answer":"On my best day, my father took me to the show."}'::jsonb, 'The child writes whatever he or she knows how to spell.', 'Offer "Cows give us milk." beside "On my best day, my father took me to the show." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check every sentence against the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M4_OC_AND_THEN', 'ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Joins every sentence with and then.', '{"question":"Improve: We woke up and then we ate and then we went.","wrong_answer":"We woke up and then we ate and then we went.","correct_answer":"We woke up early. After breakfast, we left for church."}'::jsonb, 'And then is the only time word the child knows.', 'Offer "We woke up and then we ate and then we went." beside "We woke up early. After breakfast, we left for church." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use first, after that, later and finally.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M4_OC_LIST', 'ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Writes a list of unconnected sentences.', '{"question":"Which is a composition, not a list?","wrong_answer":"I like dogs. Rain is wet. My name is Otieno.","correct_answer":"I love our dog Simba. Every evening he waits for me at the gate."}'::jsonb, 'Each sentence is written alone.', 'Offer "I like dogs. Rain is wet. My name is Otieno." beside "I love our dog Simba. Every evening he waits for me at the gate." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every sentence should follow from the one before.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION.M4_OC_NO_ENDING', 'ENGL.G4.WRITIN.T2_CREATIVE_WRITING.OPEN_COMPOSITION', 'Stops suddenly with no ending.', '{"question":"What is missing: \"We went to the river. We saw a crocodile.\"","wrong_answer":"nothing","correct_answer":"an ending that tells what happened in the end"}'::jsonb, 'The child stops when the page or the time runs out.', 'Offer "nothing" beside "an ending that tells what happened in the end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan the ending before you start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS.M_POL_DEMAND', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS', 'Makes a request as a demand.', '{"question":"You want to borrow a pen. What do you say?","wrong_answer":"Give me your pen.","correct_answer":"May I please borrow your pen?"}'::jsonb, 'Says the shortest thing that gets the pen.', 'A question like "You want to borrow a pen. What do you say?" with "Give me your pen." among the options.', 'Have the child say both forms aloud and say why one fits: "May I please borrow your pen?", not "Give me your pen.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS.M_POL_NO_THANKS', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS', 'Does not say thank you.', '{"question":"Your friend helps you. What do you say?","wrong_answer":"Okay.","correct_answer":"Thank you for helping me."}'::jsonb, 'Does not see thanks as needed.', 'A question like "Your friend helps you. What do you say?" with "Okay." among the options.', 'Have the child say both forms aloud and say why one fits: "Thank you for helping me.", not "Okay.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS.M_POL_RUDE_REFUSAL', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS', 'Refuses in a rude way.', '{"question":"You cannot lend your book. What do you say?","wrong_answer":"No. Go away.","correct_answer":"I am sorry, I cannot lend it today."}'::jsonb, 'Does not know how to say no politely.', 'A question like "You cannot lend your book. What do you say?" with "No. Go away." among the options.', 'Have the child say both forms aloud and say why one fits: "I am sorry, I cannot lend it today.", not "No. Go away.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS.M_POL_NO_SORRY', 'ENGL.G4.LISTEN.T3_PRONUNCIATION_AND_VO.POLITE_WORDS', 'Does not say sorry after a mistake.', '{"question":"You step on someone''s foot. What do you say?","wrong_answer":"Move.","correct_answer":"Sorry, I did not see you."}'::jsonb, 'Does not see that sorry is needed.', 'A question like "You step on someone''s foot. What do you say?" with "Move." among the options.', 'Have the child say both forms aloud and say why one fits: "Sorry, I did not see you.", not "Move.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN.M_PAT_VERB_FORM', 'ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN', 'Puts to, -s or -ing after May I or Could you.', '{"question":"May I ___ in?","wrong_answer":"to come","correct_answer":"come"}'::jsonb, 'Thinks every verb needs "to" before it.', 'A question like "May I ___ in?" with "to come" among the options.', 'Have the child say both forms aloud and say why one fits: "come", not "to come".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN.M_PAT_NO_PLEASE', 'ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN', 'Makes a request as a command.', '{"question":"Which is polite? Give me water.","wrong_answer":"Give me water.","correct_answer":"Could you give me some water, please?"}'::jsonb, 'Uses the command that is quick and short.', 'A question like "Which is polite? Give me water." with "Give me water." among the options.', 'Have the child say both forms aloud and say why one fits: "Could you give me some water, please?", not "Give me water.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN.M_PAT_WOULD_LIKE_FORM', 'ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN', 'Writes Would you like with -ing or a wrong verb form.', '{"question":"___ you like some tea?","wrong_answer":"Do","correct_answer":"Would"}'::jsonb, 'Mixes Would you like with Do you want.', 'A question like "___ you like some tea?" with "Do" among the options.', 'Have the child say both forms aloud and say why one fits: "Would", not "Do".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN.M_PAT_ORDER', 'ENGL.G4.LANGUA.T3_LANGUAGE_PATTERN.POLITE_PATTERN', 'Puts the words of the request in the wrong order.', '{"question":"Could ___ help me?","wrong_answer":"help you","correct_answer":"you help"}'::jsonb, 'Does not move the helping word before the subject.', 'A question like "Could ___ help me?" with "help you" among the options.', 'Have the child say both forms aloud and say why one fits: "you help", not "help you".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING.M4_HW_OFF_LINE', 'ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING', 'Letters float above or sink below the line.', '{"question":"Copy: Our school is clean.","wrong_answer":"letters bounce above and below the line","correct_answer":"every letter sits on the line"}'::jsonb, 'The child does not use the ruled line as a base.', 'Offer "letters bounce above and below the line" beside "every letter sits on the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sit every letter on the line, like people on a bench.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING.M4_HW_MIXED_CASE', 'ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING', 'Mixes capital and small letters inside words.', '{"question":"Copy: bread","wrong_answer":"brEaD","correct_answer":"bread"}'::jsonb, 'Capital forms of some letters are easier and slip in.', 'Offer "brEaD" beside "bread" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Small letters inside a word; a capital only at the start of a name or sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING.M4_HW_B_D', 'ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING', 'Reverses b and d.', '{"question":"Write: bed","wrong_answer":"deb","correct_answer":"bed"}'::jsonb, 'B and d are mirror images and are confused.', 'Offer "deb" beside "bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'B: bat then ball; d: drum then stick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING.M4_HW_NO_SPACES', 'ENGL.G4.WRITIN.T3_MECHANICS_OF_WRITING.HANDWRITING', 'Leaves no space between words.', '{"question":"Copy: We like reading.","wrong_answer":"Welikereading.","correct_answer":"We like reading."}'::jsonb, 'The child copies letter by letter, not word by word.', 'Offer "Welikereading." beside "We like reading." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Leave a finger space between words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS.M_FA_NEAR_MEANING', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS', 'Picks a first aid word that is near in meaning but wrong.', '{"question":"A ___ is a cloth wrapped round a cut.","wrong_answer":"bruise","correct_answer":"bandage"}'::jsonb, 'Mixes up words in the same topic.', 'A question like "A ___ is a cloth wrapped round a cut." with "bruise" among the options.', 'Have the child say both forms aloud and say why one fits: "bandage", not "bruise".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS.M_FA_WOUND_BRUISE', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS', 'Mixes up wound and bruise.', '{"question":"A ___ is a dark mark on the skin where you were hit.","wrong_answer":"wound","correct_answer":"bruise"}'::jsonb, 'Treats the two words as the same.', 'A question like "A ___ is a dark mark on the skin where you were hit." with "wound" among the options.', 'Have the child say both forms aloud and say why one fits: "bruise", not "wound".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS.M_FA_SPRAIN_BREAK', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS', 'Mixes up sprain and break.', '{"question":"When you twist your ankle, it may be a ___.","wrong_answer":"ambulance","correct_answer":"sprain"}'::jsonb, 'Does not know the words.', 'A question like "When you twist your ankle, it may be a ___." with "ambulance" among the options.', 'Have the child say both forms aloud and say why one fits: "sprain", not "ambulance".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M4_WS_EQUAL', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Gives every syllable the same strength.', '{"question":"Say: hospital","wrong_answer":"HOS-PI-TAL (all equal)","correct_answer":"HOS-pi-tal"}'::jsonb, 'Kenyan languages are syllable-timed, so each syllable gets equal weight.', 'Offer "HOS-PI-TAL (all equal)" beside "HOS-pi-tal" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One syllable is strong; the others are short and weak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M4_WS_SECOND', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Stresses the second syllable.', '{"question":"Say: accident","wrong_answer":"ac-CI-dent","correct_answer":"AC-ci-dent"}'::jsonb, 'Stress is placed on the next-to-last syllable, as in Kiswahili.', 'Offer "ac-CI-dent" beside "AC-ci-dent" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Clap the strong part: AC-ci-dent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M4_WS_LAST', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Stresses the last syllable.', '{"question":"Say: bandage","wrong_answer":"ban-DAGE","correct_answer":"BAN-dage"}'::jsonb, 'The child stresses the syllable that looks longest in spelling.', 'Offer "ban-DAGE" beside "BAN-dage" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Most two-syllable nouns are strong at the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS.M4_WS_SPELLING_VOWEL', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.WORD_STRESS', 'Says the weak vowel fully as it is spelt.', '{"question":"Say: ambulance","wrong_answer":"am-bu-LANCE with a full a","correct_answer":"AM-bju-lens"}'::jsonb, 'Reading by spelling: every vowel is given its letter sound.', 'Offer "am-bu-LANCE with a full a" beside "AM-bju-lens" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Weak syllables are quick and soft.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS.M4_FA_BANDAGE_PLASTER', 'ENGL.G4.LISTEN.T4_PRONUNCIATION_AND_VO.FIRST_AID_WORDS', 'Calls a small sticky plaster a bandage, or a long cloth bandage a plaster.', '{"question":"You cut your finger a little. You put on a ...","wrong_answer":"bandage","correct_answer":"plaster"}'::jsonb, 'Both cover a wound and the names are swapped.', 'Offer "bandage" beside "plaster" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A plaster sticks on a small cut; a bandage is wrapped round.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS.M_VIS_WRONG_ROW', 'ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS', 'Reads the wrong row or column of a table.', '{"question":"What time does the bus to Kisumu leave?","wrong_answer":"10:30 am","correct_answer":"8:00 am"}'::jsonb, 'Looks at the nearest number instead of the row for Kisumu.', 'A question like "What time does the bus to Kisumu leave?" with "10:30 am" among the options.', 'Have the child say both forms aloud and say why one fits: "8:00 am", not "10:30 am".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS.M_VIS_NEARBY_DETAIL', 'ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS', 'Picks a nearby detail on the notice.', '{"question":"Which day is the clinic closed?","wrong_answer":"Saturday","correct_answer":"Sunday"}'::jsonb, 'Picks the line next to the answer.', 'A question like "Which day is the clinic closed?" with "Saturday" among the options.', 'Have the child say both forms aloud and say why one fits: "Sunday", not "Saturday".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS.M_VIS_PURPOSE', 'ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS', 'Says the wrong purpose for a visual.', '{"question":"What is the notice for?","wrong_answer":"to sell shoes","correct_answer":"to tell people the time of the meeting"}'::jsonb, 'Reads one word and guesses.', 'A question like "What is the notice for?" with "to sell shoes" among the options.', 'Have the child say both forms aloud and say why one fits: "to tell people the time of the meeting", not "to sell shoes".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS.M4_VIS_TITLE_IGNORED', 'ENGL.G4.READIN.T4_INTENSIVE_READING_VI.VISUALS', 'Answers without reading the title or the key.', '{"question":"A chart titled \"Clinic hours\" shows 8 to 5. What does 8 to 5 tell you?","wrong_answer":"the price","correct_answer":"when the clinic is open"}'::jsonb, 'The child goes straight to the numbers.', 'Offer "the price" beside "when the clinic is open" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the title first: it tells you what the numbers mean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS.M_PRO_SUBJECT_AS_OBJECT', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS', 'Uses I, he, we or they after a verb or a small word.', '{"question":"Mum gave the book to ___.","wrong_answer":"I","correct_answer":"me"}'::jsonb, 'Hears "Him and I" in speech and over-corrects.', 'A question like "Mum gave the book to ___." with "I" among the options.', 'Have the child say both forms aloud and say why one fits: "me", not "I".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS.M_PRO_OBJECT_AS_SUBJECT', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS', 'Uses me, him, us or them before the verb.', '{"question":"___ went to the market.","wrong_answer":"Me and Wanjiru","correct_answer":"Wanjiru and I"}'::jsonb, 'Uses the object form in a pair of names.', 'A question like "___ went to the market." with "Me and Wanjiru" among the options.', 'Have the child say both forms aloud and say why one fits: "Wanjiru and I", not "Me and Wanjiru".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS.M_PRO_NOUN_AND_PRONOUN', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS', 'Says the noun and then repeats it with a pronoun.', '{"question":"Wanjiru ___ is tall.","wrong_answer":"she","correct_answer":"no pronoun"}'::jsonb, 'Copies the pattern of speech where the name is said and then repeated.', 'A question like "Wanjiru ___ is tall." with "she" among the options.', 'Have the child say both forms aloud and say why one fits: "no pronoun", not "she".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS.M_PRO_GENDER', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.PERSONAL_PRONOUNS', 'Says he for a girl, or she for a boy.', '{"question":"Akinyi is my sister. ___ is nine.","wrong_answer":"He","correct_answer":"She"}'::jsonb, 'Kiswahili has one word (yeye) for he and she.', 'A question like "Akinyi is my sister. ___ is nine." with "He" among the options.', 'Have the child say both forms aloud and say why one fits: "She", not "He".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS.M_POS_DETERMINER_FOR_PRONOUN', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS', 'Writes my, your or her when no noun follows.', '{"question":"That bag is ___.","wrong_answer":"my","correct_answer":"mine"}'::jsonb, 'Does not tell the two sets apart.', 'A question like "That bag is ___." with "my" among the options.', 'Have the child say both forms aloud and say why one fits: "mine", not "my".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS.M_POS_PRONOUN_BEFORE_NOUN', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS', 'Writes mine, yours or hers before a noun.', '{"question":"This is ___ pencil.","wrong_answer":"mine","correct_answer":"my"}'::jsonb, 'Over-uses the form that stands alone.', 'A question like "This is ___ pencil." with "mine" among the options.', 'Have the child say both forms aloud and say why one fits: "my", not "mine".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS.M_POS_APOSTROPHE', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS', 'Writes your''s, her''s or our''s.', '{"question":"The blue pen is ___.","wrong_answer":"your''s","correct_answer":"yours"}'::jsonb, 'Thinks a belonging word needs an apostrophe, as in a name.', 'A question like "The blue pen is ___." with "your''s" among the options.', 'Have the child say both forms aloud and say why one fits: "yours", not "your''s".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS.M_POS_WRONG_PERSON', 'ENGL.G4.LANGUA.T4_WORD_CLASSES_PRONOUN.POSSESSIVE_PRONOUNS', 'Uses the possessive of another person.', '{"question":"Wafula, this book is not mine. It is ___.","wrong_answer":"his","correct_answer":"yours"}'::jsonb, 'Does not follow who is speaking and who is spoken to.', 'A question like "Wafula, this book is not mine. It is ___." with "his" among the options.', 'Have the child say both forms aloud and say why one fits: "yours", not "his".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS.M_LTR_PART_MIX', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS', 'Mixes up the parts of a letter.', '{"question":"Which part says \"Dear Amina,\"?","wrong_answer":"closing","correct_answer":"greeting"}'::jsonb, 'Does not know the names of the parts.', 'A question like "Which part says "Dear Amina,"?" with "closing" among the options.', 'Have the child say both forms aloud and say why one fits: "greeting", not "closing".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS.M_LTR_ORDER', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS', 'Puts the parts of the letter in the wrong order.', '{"question":"Which comes first in a friendly letter?","wrong_answer":"the closing","correct_answer":"your address and the date"}'::jsonb, 'Does not know the usual order.', 'A question like "Which comes first in a friendly letter?" with "the closing" among the options.', 'Have the child say both forms aloud and say why one fits: "your address and the date", not "the closing".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS.M_LTR_NO_COMMA', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS', 'Leaves the comma out after the greeting or the closing.', '{"question":"Which is correct?","wrong_answer":"Dear Amina","correct_answer":"Dear Amina,"}'::jsonb, 'Writes the greeting as a plain word group.', 'A question like "Which is correct?" with "Dear Amina" among the options.', 'Have the child say both forms aloud and say why one fits: "Dear Amina,", not "Dear Amina".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS.M_LTR_RECEIVER_ADDRESS', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.LETTER_PARTS', 'Writes the receiver''s address at the top of a friendly letter.', '{"question":"Whose address goes at the top?","wrong_answer":"the person getting the letter","correct_answer":"the writer"}'::jsonb, 'Copies the pattern of a formal letter.', 'A question like "Whose address goes at the top?" with "the person getting the letter" among the options.', 'Have the child say both forms aloud and say why one fits: "the writer", not "the person getting the letter".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER.M4_FL_NO_ADDRESS', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER', 'Leaves out the address and date at the top.', '{"question":"What comes first in a friendly letter?","wrong_answer":"Dear Juma,","correct_answer":"my address and the date, top right"}'::jsonb, 'The child starts with the greeting as in speech.', 'Offer "Dear Juma," beside "my address and the date, top right" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Address and date first, top right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER.M4_FL_OFFICIAL_CLOSE', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER', 'Closes a friendly letter like an official letter.', '{"question":"Best closing for a letter to your cousin?","wrong_answer":"Yours faithfully,","correct_answer":"Your loving cousin,"}'::jsonb, 'Official letter phrases from older siblings are copied.', 'Offer "Yours faithfully," beside "Your loving cousin," in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Friendly letters close with Your friend or Your loving cousin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER.M4_FL_ONE_BLOCK', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER', 'Writes the body as one block with no paragraphs.', '{"question":"How should the body be set out?","wrong_answer":"one long block","correct_answer":"short paragraphs, one idea each"}'::jsonb, 'Paragraphs are not yet used in letters.', 'Offer "one long block" beside "short paragraphs, one idea each" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start a new paragraph for each new idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER.M4_FL_NO_NAME', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.FRIENDLY_LETTER', 'Forgets to write his or her name at the end.', '{"question":"What comes after \"Your friend,\"?","wrong_answer":"nothing","correct_answer":"my name"}'::jsonb, 'The child thinks the reader knows who wrote it.', 'Offer "nothing" beside "my name" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Always end with your name under the closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE.M4_SM_NO_NAME', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE', 'Sends an SMS without saying who it is from.', '{"question":"You use your mother''s phone to tell your teacher you are sick. What must the SMS include?","wrong_answer":"I am sick.","correct_answer":"Good morning Teacher. This is Amina Grade 4. I am sick today."}'::jsonb, 'The child assumes the reader knows the phone owner.', 'Offer "I am sick." beside "Good morning Teacher. This is Amina Grade 4. I am sick today." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say who you are in the message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE.M4_SM_TEXTSPEAK', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE', 'Uses short forms the reader may not understand.', '{"question":"Which SMS is clear for your grandfather?","wrong_answer":"Gud mrng, cum 2 skul 2mrw","correct_answer":"Good morning. Please come to school tomorrow."}'::jsonb, 'Text-speak seen on phones is copied.', 'Offer "Gud mrng, cum 2 skul 2mrw" beside "Good morning. Please come to school tomorrow." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write words in full for an older reader.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE.M4_SM_LETTER_FORMAT', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE', 'Writes an SMS like a letter with addresses.', '{"question":"Which is an SMS?","wrong_answer":"P.O. Box 12, Kitale. Dear Mum, ...","correct_answer":"Mum, I have reached school safely. Amina"}'::jsonb, 'The child applies the letter format to every message.', 'Offer "P.O. Box 12, Kitale. Dear Mum, ..." beside "Mum, I have reached school safely. Amina" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'An SMS is short: greeting, message, name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE.M4_SM_MISSING_DETAIL', 'ENGL.G4.WRITIN.T4_FUNCTIONAL_WRITING.SMS_MESSAGE', 'Leaves out what the reader needs to know or do.', '{"question":"SMS to say the meeting has moved. What is missing: \"The meeting has moved.\"?","wrong_answer":"nothing","correct_answer":"the new day and time"}'::jsonb, 'The child knows the details and forgets the reader does not.', 'Offer "nothing" beside "the new day and time" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: what does the reader need to know?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS.M_NUT_NEAR_MEANING', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS', 'Picks a food word that is near in meaning but wrong.', '{"question":"Beans and meat give us ___.","wrong_answer":"carbohydrates","correct_answer":"protein"}'::jsonb, 'Mixes up the food groups.', 'A question like "Beans and meat give us ___." with "carbohydrates" among the options.', 'Have the child say both forms aloud and say why one fits: "protein", not "carbohydrates".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS.M_NUT_VITAMIN_FIBRE', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS', 'Mixes up vitamins and fibre.', '{"question":"___ help us stay healthy and are found in fruits.","wrong_answer":"Fibre","correct_answer":"Vitamins"}'::jsonb, 'Treats all nutrients as one.', 'A question like "___ help us stay healthy and are found in fruits." with "Fibre" among the options.', 'Have the child say both forms aloud and say why one fits: "Vitamins", not "Fibre".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS.M_NUT_BALANCED', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS', 'Thinks a balanced diet is one food in a large amount.', '{"question":"A balanced diet has ___.","wrong_answer":"only ugali","correct_answer":"all the food groups in the right amounts"}'::jsonb, 'Does not know the meaning of balanced.', 'A question like "A balanced diet has ___." with "only ugali" among the options.', 'Have the child say both forms aloud and say why one fits: "all the food groups in the right amounts", not "only ugali".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN.M4_LB_DO_NOT_S', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN', 'Keeps -s or a past form after do not.', '{"question":"I like rice but I do not ... fish. (like)","wrong_answer":"likes","correct_answer":"like"}'::jsonb, 'The -s rule for he and she is carried into every sentence.', 'Offer "likes" beside "like" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After do not, the verb is plain: do not like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN.M4_LB_AND_FOR_BUT', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN', 'Joins a like and a dislike with and.', '{"question":"I like mangoes ... I do not like pawpaws.","wrong_answer":"and","correct_answer":"but"}'::jsonb, 'And is the joining word the child uses most.', 'Offer "and" beside "but" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'But joins two ideas that go different ways.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN.M4_LB_NOT_LIKE', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN', 'Leaves out do in the negative.', '{"question":"I like tea but I ... milk.","wrong_answer":"not like","correct_answer":"do not like"}'::jsonb, 'A word-for-word translation (sipendi = not like).', 'Offer "not like" beside "do not like" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'English needs do: I do not like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN.M4_LB_LIKE_ING_TO', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.LIKE_BUT_PATTERN', 'Writes like to eating or like to eats.', '{"question":"I like ... ugali.","wrong_answer":"to eating","correct_answer":"eating"}'::jsonb, 'Two patterns (like to eat, like eating) are mixed.', 'Offer "to eating" beside "eating" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Like eating or like to eat, never like to eating.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS.M4_NUT_FRUIT_PROTEIN', 'ENGL.G4.LISTEN.T5_PRONUNCIATION_AND_VO.NUTRITION_WORDS', 'Puts beans or eggs with fruit, or fruit with body-building food.', '{"question":"Beans are mainly for ...","wrong_answer":"giving vitamins like fruit","correct_answer":"building the body (protein)"}'::jsonb, 'Food groups are learnt as a list, not by what each does.', 'Offer "giving vitamins like fruit" beside "building the body (protein)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Beans, eggs and fish build the body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL.M_SCAN_NEAR_NUMBER', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL', 'Picks another number from the text.', '{"question":"How much is a ticket?","wrong_answer":"60 shillings","correct_answer":"50 shillings"}'::jsonb, 'Does not look for the key word.', 'A question like "How much is a ticket?" with "60 shillings" among the options.', 'Have the child say both forms aloud and say why one fits: "50 shillings", not "60 shillings".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL.M_SCAN_WRONG_KEYWORD', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL', 'Looks for the wrong key word.', '{"question":"When does the show start?","wrong_answer":"at 6 pm","correct_answer":"at 4 pm"}'::jsonb, 'Uses a word that is not the key word.', 'A question like "When does the show start?" with "at 6 pm" among the options.', 'Have the child say both forms aloud and say why one fits: "at 4 pm", not "at 6 pm".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL.M_SCAN_TOO_LONG', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL', 'Reads the whole text to find one detail.', '{"question":"What is the name of the guide?","wrong_answer":"a long answer from the whole text","correct_answer":"Mr Otieno"}'::jsonb, 'Does not scan.', 'A question like "What is the name of the guide?" with "a long answer from the whole text" among the options.', 'Have the child say both forms aloud and say why one fits: "Mr Otieno", not "a long answer from the whole text".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING.M4_SR_COVER', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING', 'Chooses a book by its cover or pictures alone.', '{"question":"You want facts about camels for a project. Which do you take?","wrong_answer":"the storybook with a camel on the cover","correct_answer":"the encyclopaedia"}'::jsonb, 'The picture matches the topic, so the child stops there.', 'Offer "the storybook with a camel on the cover" beside "the encyclopaedia" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: will this book answer my question?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING.M4_SR_TOO_HARD', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING', 'Chooses a book far above his or her level.', '{"question":"Which book should you read alone for practice?","wrong_answer":"the thick book for Grade 8","correct_answer":"a Grade 4 graded reader"}'::jsonb, 'The child thinks a harder book makes a better reader.', 'Offer "the thick book for Grade 8" beside "a Grade 4 graded reader" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For practice, choose a book where you know almost every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING.M4_SR_THICKNESS', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING', 'Thinks a thicker book has more information.', '{"question":"Which tells you the meaning of a word fastest?","wrong_answer":"the thickest novel","correct_answer":"a dictionary"}'::jsonb, 'Size is taken as a sign of usefulness.', 'Offer "the thickest novel" beside "a dictionary" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose by what the book is for, not by its size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING.M4_SR_WRONG_TYPE', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SELECT_READING', 'Chooses a text of the wrong type for the purpose.', '{"question":"You want to make mandazi. Which do you read?","wrong_answer":"a poem about food","correct_answer":"a recipe"}'::jsonb, 'All books about the topic seem equal.', 'Offer "a poem about food" beside "a recipe" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Instructions are in a recipe; feelings are in a poem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING.M4_IR_STOPS_AT_WORD', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING', 'Stops reading at the first unknown word.', '{"question":"You meet the word \"harvest\" and do not know it. What do you do?","wrong_answer":"stop and close the book","correct_answer":"read on and use the sentence and picture to guess"}'::jsonb, 'The child believes every word must be known.', 'Offer "stop and close the book" beside "read on and use the sentence and picture to guess" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Skip, read on, then come back and guess from the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING.M4_IR_PICTURES_ONLY', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING', 'Looks at the pictures and turns pages without reading the words.', '{"question":"After ten minutes, what was the story about?","wrong_answer":"a lion (from the cover only)","correct_answer":"the lion who lost his roar and how he found it"}'::jsonb, 'The pictures feel like reading.', 'Offer "a lion (from the cover only)" beside "the lion who lost his roar and how he found it" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read every line; the pictures only help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING.M4_IR_CANNOT_RETELL', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING', 'Reads the words but cannot say what happened.', '{"question":"Tell me what happened in the chapter.","wrong_answer":"I read it all.","correct_answer":"Juma lost his goat and found it by the river."}'::jsonb, 'Reading is treated as saying the words.', 'Offer "I read it all." beside "Juma lost his goat and found it by the river." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop after each page and tell yourself what happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING.M4_IR_SKIPS_TO_END', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.INDEPENDENT_READING', 'Skips to the end to finish quickly.', '{"question":"How did the girl get home?","wrong_answer":"I do not know, I read the last page.","correct_answer":"Her uncle drove her on his motorbike."}'::jsonb, 'The aim becomes finishing, not understanding.', 'Offer "I do not know, I read the last page." beside "Her uncle drove her on his motorbike." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read in order; the middle explains the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL.M4_SCAN_FIRST_MATCH', 'ENGL.G4.READIN.T5_EXTENSIVE_READING.SCAN_FOR_DETAIL', 'Stops at the first place the key word appears, even when the answer is later.', '{"question":"Notice: \"Football on Monday. Match moved: football on Friday at 4.\" When is football this week?","wrong_answer":"Monday","correct_answer":"Friday at 4"}'::jsonb, 'The first match of the key word is taken.', 'Offer "Monday" beside "Friday at 4" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check every place the key word appears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES.M_ADJ_NOUN_AS_ADJ', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES', 'Picks the noun as the describing word.', '{"question":"The red bus stopped.","wrong_answer":"bus","correct_answer":"red"}'::jsonb, 'Does not tell what the word does in the sentence.', 'A question like "The red bus stopped." with "bus" among the options.', 'Have the child say both forms aloud and say why one fits: "red", not "bus".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES.M_ADJ_VERB_AS_ADJ', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES', 'Picks the verb as the describing word.', '{"question":"The tall girl ran home.","wrong_answer":"ran","correct_answer":"tall"}'::jsonb, 'Takes any word that adds meaning as a describing word.', 'A question like "The tall girl ran home." with "ran" among the options.', 'Have the child say both forms aloud and say why one fits: "tall", not "ran".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES.M_ADJ_ADVERB_AS_ADJ', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES', 'Picks an adverb as the adjective.', '{"question":"The small boy walked slowly.","wrong_answer":"slowly","correct_answer":"small"}'::jsonb, 'Does not separate describing a noun from describing a verb.', 'A question like "The small boy walked slowly." with "slowly" among the options.', 'Have the child say both forms aloud and say why one fits: "small", not "slowly".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES.M_ADJ_ARTICLE_AS_ADJ', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVES', 'Picks a, an or the as the adjective.', '{"question":"Mama bought a sweet mango.","wrong_answer":"a","correct_answer":"sweet"}'::jsonb, 'Thinks any small word before a noun describes it.', 'A question like "Mama bought a sweet mango." with "a" among the options.', 'Have the child say both forms aloud and say why one fits: "sweet", not "a".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER.M_ADO_SHAPE_BEFORE_SIZE', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER', 'Puts the shape before the size.', '{"question":"She sat on a ___ stool.","wrong_answer":"round big","correct_answer":"big round"}'::jsonb, 'No fixed order is known.', 'A question like "She sat on a ___ stool." with "round big" among the options.', 'Have the child say both forms aloud and say why one fits: "big round", not "round big".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER.M_ADO_AFTER_NOUN', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER', 'Puts the adjective after the noun.', '{"question":"Amina has a ___.","wrong_answer":"ball big","correct_answer":"big ball"}'::jsonb, 'Kiswahili puts the adjective after the noun.', 'A question like "Amina has a ___." with "ball big" among the options.', 'Have the child say both forms aloud and say why one fits: "big ball", not "ball big".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER.M_ADO_NO_AND', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER', 'Joins two adjectives with and or a comma.', '{"question":"a ___ table","wrong_answer":"big and round","correct_answer":"big round"}'::jsonb, 'Copies the way two things are joined in speech.', 'A question like "a ___ table" with "big and round" among the options.', 'Have the child say both forms aloud and say why one fits: "big round", not "big and round".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER.M4_ADO_COLOUR_FIRST', 'ENGL.G4.LANGUA.T5_WORD_CLASSES_ADJECTI.ADJECTIVE_ORDER', 'Puts the colour before the size.', '{"question":"a ... ball (red, big)","wrong_answer":"red big","correct_answer":"big red"}'::jsonb, 'The order is not yet fixed: opinion, size, shape, colour.', 'Offer "red big" beside "big red" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Size comes before colour: a big red ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS.M_NAR_PART_MIX', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS', 'Puts the end of the story at the beginning.', '{"question":"Which part tells how the story ends?","wrong_answer":"the beginning","correct_answer":"the end"}'::jsonb, 'Does not know what each part does.', 'A question like "Which part tells how the story ends?" with "the beginning" among the options.', 'Have the child say both forms aloud and say why one fits: "the end", not "the beginning".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS.M_NAR_SETTING_CHARACTER', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS', 'Mixes up setting and characters.', '{"question":"Which tells where and when a story happens?","wrong_answer":"the characters","correct_answer":"the setting"}'::jsonb, 'Uses the two words as if they meant the same.', 'A question like "Which tells where and when a story happens?" with "the characters" among the options.', 'Have the child say both forms aloud and say why one fits: "the setting", not "the characters".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS.M_NAR_PROBLEM_END', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS', 'Places the problem at the end instead of the middle.', '{"question":"Where does the problem of a story usually come?","wrong_answer":"at the end","correct_answer":"in the middle"}'::jsonb, 'Thinks a story needs the problem last.', 'A question like "Where does the problem of a story usually come?" with "at the end" among the options.', 'Have the child say both forms aloud and say why one fits: "in the middle", not "at the end".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS.M_NAR_TITLE', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_PARTS', 'Thinks the title tells the whole story.', '{"question":"What does a title do?","wrong_answer":"tells the whole story","correct_answer":"gives a short name to the story"}'::jsonb, 'Does not know the purpose of a title.', 'A question like "What does a title do?" with "tells the whole story" among the options.', 'Have the child say both forms aloud and say why one fits: "gives a short name to the story", not "tells the whole story".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER.M_PAR_ORDER_REVERSED', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Puts the sentences in the reverse order.', '{"question":"Put the four sentences in order.","wrong_answer":"D C B A","correct_answer":"A B C D"}'::jsonb, 'Starts from the sentence that sounds like an ending.', 'A question like "Put the four sentences in order." with "D C B A" among the options.', 'Have the child say both forms aloud and say why one fits: "A B C D", not "D C B A".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER.M_PAR_ORDER_SWAPPED', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Swaps two neighbouring sentences.', '{"question":"Put the four sentences in order.","wrong_answer":"A C B D","correct_answer":"A B C D"}'::jsonb, 'Does not check the sequence words (first, then, next).', 'A question like "Put the four sentences in order." with "A C B D" among the options.', 'Have the child say both forms aloud and say why one fits: "A B C D", not "A C B D".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER.M_PAR_TOPIC_DETAIL', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Chooses a detail as the topic sentence.', '{"question":"Which is the topic sentence?","wrong_answer":"a detail","correct_answer":"the sentence that tells what the paragraph is about"}'::jsonb, 'Picks the first sentence the eye meets.', 'A question like "Which is the topic sentence?" with "a detail" among the options.', 'Have the child say both forms aloud and say why one fits: "the sentence that tells what the paragraph is about", not "a detail".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M4_NC_TENSE_SWITCH', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Switches between past and present tense.', '{"question":"Correct: \"Yesterday Otieno goes to the market and bought eggs.\"","wrong_answer":"goes ... bought","correct_answer":"went ... bought"}'::jsonb, 'The present is used when the child is excited or unsure of the past form.', 'Offer "goes ... bought" beside "went ... bought" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell the whole story in the past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M4_NC_NO_PROBLEM', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Writes events with no problem to solve.', '{"question":"What makes a story interesting?","wrong_answer":"many events","correct_answer":"a problem in the middle that is solved at the end"}'::jsonb, 'A story is seen as a diary of events.', 'Offer "many events" beside "a problem in the middle that is solved at the end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give your character a problem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M4_NC_TOO_SHORT', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Writes far fewer words than asked.', '{"question":"The task asks for 60 to 80 words. Is 25 words enough?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'The child stops when the main event is told.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add who, where, how they felt and what happened next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION.M4_NC_I_WOKE_UP', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.NARRATIVE_COMPOSITION', 'Starts every story with waking up and ends with going to bed.', '{"question":"Which beginning is better for a story about a lost goat?","wrong_answer":"I woke up, brushed my teeth and ate breakfast.","correct_answer":"Our goat Kibet was missing from the shed."}'::jsonb, 'A taught opening is used for every story.', 'Offer "I woke up, brushed my teeth and ate breakfast." beside "Our goat Kibet was missing from the shed." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Begin close to the main event.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER.M4_PAR_ENDING_FIRST', 'ENGL.G4.WRITIN.T5_CREATIVE_WRITING.PARAGRAPH_ORDER', 'Puts the concluding sentence first.', '{"question":"Which goes last: \"So the day ended happily.\"?","wrong_answer":"first","correct_answer":"last"}'::jsonb, 'The sentence sounds important, so it is placed first.', 'Offer "first" beside "last" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Words like so, finally and in the end close a paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS.M_NET_NEAR_MEANING', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS', 'Picks an internet word that is near in meaning but wrong.', '{"question":"The messages you receive are kept in your ___.","wrong_answer":"attachment","correct_answer":"inbox"}'::jsonb, 'Mixes up the parts of an email.', 'A question like "The messages you receive are kept in your ___." with "attachment" among the options.', 'Have the child say both forms aloud and say why one fits: "inbox", not "attachment".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS.M_NET_PASSWORD_SHARED', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS', 'Thinks a password can be shared with friends.', '{"question":"A password should be shared with ___.","wrong_answer":"friends","correct_answer":"no one except a trusted adult"}'::jsonb, 'Does not know why a password is secret.', 'A question like "A password should be shared with ___." with "friends" among the options.', 'Have the child say both forms aloud and say why one fits: "no one except a trusted adult", not "friends".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS.M_NET_STRANGER', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS', 'Replies to or trusts a stranger online.', '{"question":"A stranger online asks where you live. You should ___.","wrong_answer":"tell him","correct_answer":"not answer and tell an adult"}'::jsonb, 'Believes a friendly message is safe.', 'A question like "A stranger online asks where you live. You should ___." with "tell him" among the options.', 'Have the child say both forms aloud and say why one fits: "not answer and tell an adult", not "tell him".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M4_IN_WH_RISE', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Lets the voice rise at the end of a WH question.', '{"question":"Say: Where do you live?","wrong_answer":"voice goes up at live","correct_answer":"voice falls at live"}'::jsonb, 'The child has learnt that questions go up and applies it to all questions.', 'Offer "voice goes up at live" beside "voice falls at live" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'WH questions fall; yes or no questions rise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M4_IN_FLAT', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Says a question with a flat voice, like a statement.', '{"question":"Say: Do you like football?","wrong_answer":"flat voice, no rise","correct_answer":"voice rises at football"}'::jsonb, 'Questions in some home languages are marked by a word, not by the voice.', 'Offer "flat voice, no rise" beside "voice rises at football" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lift the voice on the last word of a yes or no question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M4_IN_STATEMENT_RISE', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Lets the voice rise at the end of a statement.', '{"question":"Say: I live in Eldoret.","wrong_answer":"voice goes up at Eldoret","correct_answer":"voice falls at Eldoret"}'::jsonb, 'Nervous speakers lift the voice as if unsure.', 'Offer "voice goes up at Eldoret" beside "voice falls at Eldoret" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A statement ends low and firm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION.M4_IN_WRONG_WORD', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTONATION', 'Stresses a small word instead of the key word.', '{"question":"Say: I sent the EMAIL yesterday (not a letter).","wrong_answer":"I sent THE email yesterday","correct_answer":"I sent the EMAIL yesterday"}'::jsonb, 'Every word is given the same weight, or the weight falls on a small word.', 'Offer "I sent THE email yesterday" beside "I sent the EMAIL yesterday" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put the strong beat on the word that carries the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS.M4_NET_DOWNLOAD_UPLOAD', 'ENGL.G4.LISTEN.T6_PRONUNCIATION_AND_VO.INTERNET_WORDS', 'Swaps download and upload.', '{"question":"You put your photo onto the school website. You ... it.","wrong_answer":"download","correct_answer":"upload"}'::jsonb, 'The two words differ by one part and are learnt together.', 'Offer "download" beside "upload" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Up goes to the internet; down comes to your device.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT.M_QUA_MUCH_COUNT', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT', 'Uses much with things that can be counted.', '{"question":"There are not ___ chairs.","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'Treats many and much as the same word.', 'A question like "There are not ___ chairs." with "much" among the options.', 'Have the child say both forms aloud and say why one fits: "many", not "much".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT.M_QUA_MANY_UNCOUNT', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT', 'Uses many with things that cannot be counted.', '{"question":"There is not ___ water.","wrong_answer":"many","correct_answer":"much"}'::jsonb, 'Over-corrects after learning many.', 'A question like "There is not ___ water." with "many" among the options.', 'Have the child say both forms aloud and say why one fits: "much", not "many".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT.M_QUA_FEW_UNCOUNT', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT', 'Uses few with something uncountable, or little with something countable.', '{"question":"We have ___ sugar left.","wrong_answer":"few","correct_answer":"little"}'::jsonb, 'Does not link few and little to what is counted.', 'A question like "We have ___ sugar left." with "few" among the options.', 'Have the child say both forms aloud and say why one fits: "little", not "few".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT.M_QUA_MUCH_IN_STATEMENT', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.COUNT_UNCOUNT', 'Uses much in a plain positive statement.', '{"question":"She has ___ friends.","wrong_answer":"much","correct_answer":"many (or a lot of)"}'::jsonb, 'Does not know that much is mostly kept for questions and negatives.', 'A question like "She has ___ friends." with "much" among the options.', 'Have the child say both forms aloud and say why one fits: "many (or a lot of)", not "much".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY.M_QSA_ANY_STATEMENT', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY', 'Uses any in a positive sentence.', '{"question":"I have ___ sugar.","wrong_answer":"any","correct_answer":"some"}'::jsonb, 'Does not tell positive from negative sentences.', 'A question like "I have ___ sugar." with "any" among the options.', 'Have the child say both forms aloud and say why one fits: "some", not "any".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY.M_QSA_SOME_NEGATIVE', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY', 'Uses some after not.', '{"question":"I do not have ___ money.","wrong_answer":"some","correct_answer":"any"}'::jsonb, 'Keeps one word for all sentences.', 'A question like "I do not have ___ money." with "some" among the options.', 'Have the child say both forms aloud and say why one fits: "any", not "some".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY.M_QSA_ENOUGH_AFTER', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY', 'Puts enough after the noun.', '{"question":"We have ___ for everyone.","wrong_answer":"food enough","correct_answer":"enough food"}'::jsonb, 'Kiswahili puts "enough" (tosha) after the noun.', 'A question like "We have ___ for everyone." with "food enough" among the options.', 'Have the child say both forms aloud and say why one fits: "enough food", not "food enough".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY.M_QSA_A_LOT_NOUN', 'ENGL.G4.LANGUA.T6_WORD_CLASS_DETERMINE.SOME_ANY', 'Writes a lot before the noun without of.', '{"question":"There are ___ mangoes.","wrong_answer":"a lot mangoes","correct_answer":"a lot of mangoes"}'::jsonb, 'Leaves out the small word of.', 'A question like "There are ___ mangoes." with "a lot mangoes" among the options.', 'Have the child say both forms aloud and say why one fits: "a lot of mangoes", not "a lot mangoes".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE.M_PIC_ORDER_REVERSED', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE', 'Gives the pictures in reverse.', '{"question":"Which order tells the story?","wrong_answer":"D, C, B, A","correct_answer":"A, B, C, D"}'::jsonb, 'Starts from the last event seen.', 'A question like "Which order tells the story?" with "D, C, B, A" among the options.', 'Have the child say both forms aloud and say why one fits: "A, B, C, D", not "D, C, B, A".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE.M_PIC_ORDER_SWAPPED', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE', 'Swaps two neighbouring pictures.', '{"question":"Which order tells the story?","wrong_answer":"A, C, B, D","correct_answer":"A, B, C, D"}'::jsonb, 'Does not check what must happen before what.', 'A question like "Which order tells the story?" with "A, C, B, D" among the options.', 'Have the child say both forms aloud and say why one fits: "A, B, C, D", not "A, C, B, D".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE.M_PIC_TENSE', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE', 'Tells the picture in the present tense when the story is in the past.', '{"question":"Which sentence tells the picture?","wrong_answer":"Wafula picks a mango.","correct_answer":"Wafula picked a mango."}'::jsonb, 'Writes what he sees now.', 'A question like "Which sentence tells the picture?" with "Wafula picks a mango." among the options.', 'Have the child say both forms aloud and say why one fits: "Wafula picked a mango.", not "Wafula picks a mango.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE.M_PIC_MISMATCH', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTURE_SEQUENCE', 'Picks a sentence that does not match the picture.', '{"question":"Which sentence tells the picture?","wrong_answer":"She sold the fruit.","correct_answer":"She picked the fruit."}'::jsonb, 'Describes a different picture.', 'A question like "Which sentence tells the picture?" with "She sold the fruit." among the options.', 'Have the child say both forms aloud and say why one fits: "She picked the fruit.", not "She sold the fruit.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M4_PC_DESCRIBES_ONLY', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Describes each picture instead of telling a story.', '{"question":"Picture 1 shows a boy and a tree. Which is better?","wrong_answer":"There is a boy. There is a tree.","correct_answer":"Wafula climbed the mango tree to pick a ripe mango."}'::jsonb, 'Picture description from lower grades is carried over.', 'Offer "There is a boy. There is a tree." beside "Wafula climbed the mango tree to pick a ripe mango." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what the people did, not only what is there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M4_PC_SKIPS_PICTURE', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Leaves out one of the pictures.', '{"question":"There are four pictures. How many parts should the story have?","wrong_answer":"three","correct_answer":"four, one for each picture"}'::jsonb, 'A picture that is hard to describe is skipped.', 'Offer "three" beside "four, one for each picture" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tick each picture as you write about it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M4_PC_PRESENT', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Tells the pictures in the present tense.', '{"question":"Which fits a story from pictures?","wrong_answer":"The girl is running to the shop.","correct_answer":"The girl ran to the shop."}'::jsonb, 'The picture is seen as happening now.', 'Offer "The girl is running to the shop." beside "The girl ran to the shop." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell the pictures as a story in the past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION.M4_PC_NO_TITLE', 'ENGL.G4.WRITIN.T6_CREATIVE_WRITING.PICTORIAL_COMPOSITION', 'Gives no title or a title that does not fit.', '{"question":"Pictures show a boy losing and finding his dog. Best title?","wrong_answer":"My School","correct_answer":"The Lost Dog"}'::jsonb, 'The title is written last or forgotten.', 'Offer "My School" beside "The Lost Dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The title names what the whole story is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST.M_SPA_BASE_FOR_PAST', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST', 'Uses the plain verb for something that happened already.', '{"question":"Yesterday I ___ to the market.","wrong_answer":"go","correct_answer":"went"}'::jsonb, 'Kiswahili shows the past in the verb start (nilienda), so the time word seems enough.', 'A question like "Yesterday I ___ to the market." with "go" among the options.', 'Have the child say both forms aloud and say why one fits: "went", not "go".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST.M_SPA_ED_ON_IRREGULAR', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST', 'Adds -ed to an irregular verb.', '{"question":"She ___ rice for lunch. (eat)","wrong_answer":"eated","correct_answer":"ate"}'::jsonb, 'Uses the regular rule for every verb.', 'A question like "She ___ rice for lunch. (eat)" with "eated" among the options.', 'Have the child say both forms aloud and say why one fits: "ate", not "eated".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST.M_SPA_DID_PLUS_PAST', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST', 'Uses did with a past form.', '{"question":"Did you ___ the film?","wrong_answer":"saw","correct_answer":"see"}'::jsonb, 'Marks the past twice.', 'A question like "Did you ___ the film?" with "saw" among the options.', 'Have the child say both forms aloud and say why one fits: "see", not "saw".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST.M_SPA_PAST_FOR_HABIT', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.SIMPLE_PAST', 'Uses the past form for a fact or a habit.', '{"question":"The sun ___ in the east.","wrong_answer":"rose","correct_answer":"rises"}'::jsonb, 'Thinks a story always needs the past.', 'A question like "The sun ___ in the east." with "rose" among the options.', 'Have the child say both forms aloud and say why one fits: "rises", not "rose".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING.M4_TT_TALK_OVER', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING', 'Starts talking before the other person has finished.', '{"question":"Your friend is telling you about her weekend. When do you speak?","wrong_answer":"as soon as I have something to say","correct_answer":"when she stops or pauses"}'::jsonb, 'Eagerness, and no habit of waiting for a pause.', 'Offer "as soon as I have something to say" beside "when she stops or pauses" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Wait for the speaker to stop, then answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING.M4_TT_ONE_WORD', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING', 'Answers with one word and stops the conversation.', '{"question":"Friend: \"Did you watch the match?\" Best reply?","wrong_answer":"Yes.","correct_answer":"Yes! Harambee Stars won. Did you watch it?"}'::jsonb, 'The child answers the question but does not hand the turn back.', 'Offer "Yes." beside "Yes! Harambee Stars won. Did you watch it?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer, add one thing, then ask a question back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING.M4_TT_LONG_TURN', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING', 'Keeps talking and does not let the other person speak.', '{"question":"You have told your story for a long time. What next?","wrong_answer":"tell another story","correct_answer":"ask your friend what she thinks"}'::jsonb, 'The child does not notice the listener wants a turn.', 'Offer "tell another story" beside "ask your friend what she thinks" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop and give the other person a turn.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING.M4_TT_OFF_TOPIC', 'ENGL.G4.LISTEN.T7_PRONUNCIATION_AND_VO.TURN_TAKING', 'Changes the topic instead of answering.', '{"question":"Friend: \"How is your new school?\" Reply?","wrong_answer":"I want a new phone.","correct_answer":"It is nice. My teacher is kind."}'::jsonb, 'The child follows his or her own thought.', 'Offer "I want a new phone." beside "It is nice. My teacher is kind." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer what the other person asked first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE.M_PRP_NO_BE', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE', 'Leaves out am, is or are.', '{"question":"She ___ reading now.","wrong_answer":"reading","correct_answer":"is reading"}'::jsonb, 'Kiswahili says "anasoma" with no separate helping word.', 'A question like "She ___ reading now." with "reading" among the options.', 'Have the child say both forms aloud and say why one fits: "is reading", not "reading".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE.M_PRP_WRONG_BE', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE', 'Uses the wrong form of be.', '{"question":"The children ___ playing.","wrong_answer":"is","correct_answer":"are"}'::jsonb, 'Does not match the helping word to the subject.', 'A question like "The children ___ playing." with "is" among the options.', 'Have the child say both forms aloud and say why one fits: "are", not "is".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE.M_PRP_NO_ING', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE', 'Writes the plain verb after is or are.', '{"question":"He is ___ now.","wrong_answer":"play","correct_answer":"playing"}'::jsonb, 'Forgets that the verb takes -ing after the helping word.', 'A question like "He is ___ now." with "play" among the options.', 'Have the child say both forms aloud and say why one fits: "playing", not "play".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE.M_PRP_ING_SPELLING', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PRESENT_PROGRESSIVE', 'Spells the -ing form wrongly.', '{"question":"She is ___ a cake.","wrong_answer":"makeing","correct_answer":"making"}'::jsonb, 'Does not drop the silent e or double the last consonant.', 'A question like "She is ___ a cake." with "makeing" among the options.', 'Have the child say both forms aloud and say why one fits: "making", not "makeing".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE.M_PAP_PRESENT_FOR_PAST', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE', 'Uses is or are for an action that was going on in the past.', '{"question":"When I arrived, Mum ___ cooking.","wrong_answer":"is","correct_answer":"was"}'::jsonb, 'Does not follow the time words of the sentence.', 'A question like "When I arrived, Mum ___ cooking." with "is" among the options.', 'Have the child say both forms aloud and say why one fits: "was", not "is".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE.M_PAP_WAS_WERE', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE', 'Mixes up was and were.', '{"question":"The boys ___ running.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Does not match the helping word to the subject.', 'A question like "The boys ___ running." with "was" among the options.', 'Have the child say both forms aloud and say why one fits: "were", not "was".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE.M_PAP_PAST_FORM', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE', 'Writes was or were with the past form of the verb.', '{"question":"He was ___ his lunch.","wrong_answer":"ate","correct_answer":"eating"}'::jsonb, 'Thinks the verb must also show the past.', 'A question like "He was ___ his lunch." with "ate" among the options.', 'Have the child say both forms aloud and say why one fits: "eating", not "ate".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE.M_PAP_NO_ING', 'ENGL.G4.LANGUA.T7_WORD_CLASSES_VERB_AS.PAST_PROGRESSIVE', 'Writes the plain verb after was or were.', '{"question":"They were ___ football.","wrong_answer":"play","correct_answer":"playing"}'::jsonb, 'Forgets the -ing ending.', 'A question like "They were ___ football." with "play" among the options.', 'Have the child say both forms aloud and say why one fits: "playing", not "play".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS.M_PUN_NO_CAPITAL_START', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS', 'Does not start a sentence with a capital letter.', '{"question":"Which is right? we went to the lake.","wrong_answer":"we went to the lake.","correct_answer":"We went to the lake."}'::jsonb, 'Writes the way a message is typed quickly.', 'A question like "Which is right? we went to the lake." with "we went to the lake." among the options.', 'Have the child say both forms aloud and say why one fits: "We went to the lake.", not "we went to the lake.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS.M_PUN_NO_FULL_STOP', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS', 'Leaves out the full stop at the end of a statement.', '{"question":"Which is right? Mum is at work","wrong_answer":"Mum is at work","correct_answer":"Mum is at work."}'::jsonb, 'Does not see where a sentence ends.', 'A question like "Which is right? Mum is at work" with "Mum is at work" among the options.', 'Have the child say both forms aloud and say why one fits: "Mum is at work.", not "Mum is at work".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS.M_PUN_CAPITAL_MID', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS', 'Writes a capital letter in the middle of a sentence for an ordinary word.', '{"question":"Which is right? My Mother went to the Market.","wrong_answer":"My Mother went to the Market.","correct_answer":"My mother went to the market."}'::jsonb, 'Thinks important words need capitals.', 'A question like "Which is right? My Mother went to the Market." with "My Mother went to the Market." among the options.', 'Have the child say both forms aloud and say why one fits: "My mother went to the market.", not "My Mother went to the Market.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS.M_PUN_NAME_LOWER', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS', 'Writes the name of a person or place with a small letter.', '{"question":"Which is right? we live in nairobi.","wrong_answer":"We live in nairobi.","correct_answer":"We live in Nairobi."}'::jsonb, 'Does not see a name as special.', 'A question like "Which is right? we live in nairobi." with "We live in nairobi." among the options.', 'Have the child say both forms aloud and say why one fits: "We live in Nairobi.", not "We live in nairobi.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS.M_PUN_I_LOWER', 'ENGL.G4.WRITIN.T7_MECHANICS_OF_WRITING.CAPITALS_FULL_STOPS', 'Writes I as a small letter.', '{"question":"Which is right? Today i played football.","wrong_answer":"Today i played football.","correct_answer":"Today I played football."}'::jsonb, 'Types i in a phone message.', 'A question like "Which is right? Today i played football." with "Today i played football." among the options.', 'Have the child say both forms aloud and say why one fits: "Today I played football.", not "Today i played football.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS.M_FRM_NEAR_MEANING', 'ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS', 'Picks a farm word that is near in meaning but wrong.', '{"question":"We ___ the maize when it is ripe.","wrong_answer":"plant","correct_answer":"harvest"}'::jsonb, 'Mixes up the steps of farming.', 'A question like "We ___ the maize when it is ripe." with "plant" among the options.', 'Have the child say both forms aloud and say why one fits: "harvest", not "plant".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS.M_FRM_LIVESTOCK_CROPS', 'ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS', 'Mixes up livestock and crops.', '{"question":"Cows, goats and sheep are ___.","wrong_answer":"crops","correct_answer":"livestock"}'::jsonb, 'Treats all farm things as one group.', 'A question like "Cows, goats and sheep are ___." with "crops" among the options.', 'Have the child say both forms aloud and say why one fits: "livestock", not "crops".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS.M_FRM_FERTILISER', 'ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS', 'Thinks fertiliser is a pest killer.', '{"question":"___ makes the soil richer so that crops grow well.","wrong_answer":"Pesticide","correct_answer":"Fertiliser"}'::jsonb, 'Does not know the two products.', 'A question like "___ makes the soil richer so that crops grow well." with "Pesticide" among the options.', 'Have the child say both forms aloud and say why one fits: "Fertiliser", not "Pesticide".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS.M4_FRM_PLANT_HARVEST', 'ENGL.G4.LISTEN.T8_PRONUNCIATION_AND_VO.FARM_WORDS', 'Swaps planting and harvesting.', '{"question":"In August the farmer picks the ripe maize. He ...","wrong_answer":"plants","correct_answer":"harvests"}'::jsonb, 'Both are farm actions with the crop.', 'Offer "plants" beside "harvests" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plant puts seeds in; harvest takes the crop out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY.M4_RF_WORD_BY_WORD', 'ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY', 'Reads word by word with a stop after each word.', '{"question":"Read: The cows went down to the river to drink.","wrong_answer":"The. cows. went. down. to. the. river.","correct_answer":"The cows went down / to the river / to drink."}'::jsonb, 'Decoding each word takes all the attention.', 'Offer "The. cows. went. down. to. the. river." beside "The cows went down / to the river / to drink." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read in groups of words that go together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY.M4_RF_IGNORES_STOPS', 'ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY', 'Reads through full stops without pausing.', '{"question":"Read: It rained. The farmers were happy.","wrong_answer":"It rained the farmers were happy","correct_answer":"It rained. (pause) The farmers were happy."}'::jsonb, 'The child reads lines, not sentences.', 'Offer "It rained the farmers were happy" beside "It rained. (pause) The farmers were happy." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop and breathe at every full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY.M4_RF_FLAT', 'ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY', 'Reads with a flat voice, with no change for questions or speech.', '{"question":"Read: \"Where is my hoe?\" shouted Baba.","wrong_answer":"flat voice for the whole line","correct_answer":"a questioning voice, then a loud shout"}'::jsonb, 'Expression is not part of what the child thinks reading is.', 'Offer "flat voice for the whole line" beside "a questioning voice, then a loud shout" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let the voice show the question and the feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY.M4_RF_TOO_FAST', 'ENGL.G4.READIN.T8_READING_FLUENCY.READ_FLUENTLY', 'Reads very fast and skips or changes small words.', '{"question":"Read: The goat ate the green grass.","wrong_answer":"The goat ate green grass. (the skipped)","correct_answer":"The goat ate the green grass."}'::jsonb, 'The child believes fast reading is good reading.', 'Offer "The goat ate green grass. (the skipped)" beside "The goat ate the green grass." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read at talking speed; every word counts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS.M_CON_NO_APOSTROPHE', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS', 'Leaves out the apostrophe.', '{"question":"I ___ like fish. (do not)","wrong_answer":"dont","correct_answer":"don''t"}'::jsonb, 'Does not know the apostrophe marks the missing letter.', 'A question like "I ___ like fish. (do not)" with "dont" among the options.', 'Have the child say both forms aloud and say why one fits: "don''t", not "dont".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS.M_CON_WRONG_PLACE', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS', 'Puts the apostrophe in the wrong place.', '{"question":"She ___ at home. (is not)","wrong_answer":"is''nt","correct_answer":"isn''t"}'::jsonb, 'Puts it between the two words instead of where the letter is missing.', 'A question like "She ___ at home. (is not)" with "is''nt" among the options.', 'Have the child say both forms aloud and say why one fits: "isn''t", not "is''nt".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS.M_CON_ITS', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS', 'Writes its for it is, or it''s for belonging to it.', '{"question":"___ raining today. (it is)","wrong_answer":"Its","correct_answer":"It''s"}'::jsonb, 'Mixes up the two words that sound the same.', 'A question like "___ raining today. (it is)" with "Its" among the options.', 'Have the child say both forms aloud and say why one fits: "It''s", not "Its".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS.M_CON_WRONG_FORM', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.CONTRACTIONS', 'Makes a short form that does not exist.', '{"question":"We ___ go. (will not)","wrong_answer":"willn''t","correct_answer":"won''t"}'::jsonb, 'Adds n''t to every helping word.', 'A question like "We ___ go. (will not)" with "willn''t" among the options.', 'Have the child say both forms aloud and say why one fits: "won''t", not "willn''t".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS.M_NEG_DOUBLE', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS', 'Uses two negative words together.', '{"question":"I do not have ___ pen.","wrong_answer":"no","correct_answer":"a"}'::jsonb, 'Copies speech where two negatives add emphasis.', 'A question like "I do not have ___ pen." with "no" among the options.', 'Have the child say both forms aloud and say why one fits: "a", not "no".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS.M_NEG_NO_DO', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS', 'Writes not before the verb with no helping word.', '{"question":"She ___ like milk.","wrong_answer":"not","correct_answer":"does not"}'::jsonb, 'Kiswahili puts a negative in the verb itself (hapendi).', 'A question like "She ___ like milk." with "not" among the options.', 'Have the child say both forms aloud and say why one fits: "does not", not "not".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS.M_NEG_VERB_S', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS', 'Keeps -s or -ed on the verb after does not or did not.', '{"question":"He does not ___ meat.","wrong_answer":"eats","correct_answer":"eat"}'::jsonb, 'Marks the verb twice.', 'A question like "He does not ___ meat." with "eats" among the options.', 'Have the child say both forms aloud and say why one fits: "eat", not "eats".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS.M_NEG_DO_WITH_BE', 'ENGL.G4.LANGUA.T8_WORD_CLASSES.NEGATIVE_STATEMENTS', 'Uses do not with am, is or are.', '{"question":"I ___ tired.","wrong_answer":"do not","correct_answer":"am not"}'::jsonb, 'Uses do not for every negative.', 'A question like "I ___ tired." with "do not" among the options.', 'Have the child say both forms aloud and say why one fits: "am not", not "do not".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY.M4_SF_FILLERS', 'ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY', 'Fills every gap with eeh or aah.', '{"question":"Talk about your favourite food.","wrong_answer":"Eeh, my favourite, eeh, food is, aah, chapati.","correct_answer":"My favourite food is chapati."}'::jsonb, 'Searching for the next word aloud; a habit from talk at home.', 'Offer "Eeh, my favourite, eeh, food is, aah, chapati." beside "My favourite food is chapati." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Close your mouth and think for a moment instead of saying eeh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY.M4_SF_TOO_FAST', 'ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY', 'Speaks so fast that listeners cannot follow.', '{"question":"Tell the class about your home.","wrong_answer":"all the words run together","correct_answer":"steady speed with short pauses"}'::jsonb, 'Nerves in front of the class.', 'Offer "all the words run together" beside "steady speed with short pauses" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pause after each sentence; breathe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY.M4_SF_WORD_SEARCH', 'ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY', 'Stops for a long time to find a word.', '{"question":"Talk about keeping healthy.","wrong_answer":"long silence, then gives up","correct_answer":"uses a simpler word and goes on"}'::jsonb, 'The child wants the exact word and will not use a simpler one.', 'Offer "long silence, then gives up" beside "uses a simpler word and goes on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'If a word will not come, say it another way and keep going.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY.M4_SF_REPEATS', 'ENGL.G4.LISTEN.T9_PRONUNCIATION_AND_VO.SPEAK_FLUENTLY', 'Repeats the start of the sentence again and again.', '{"question":"Talk about your family.","wrong_answer":"I have, I have, I have two sisters.","correct_answer":"I have two sisters."}'::jsonb, 'Restarting to buy time.', 'Offer "I have, I have, I have two sisters." beside "I have two sisters." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start once and go to the end of the sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS.M_ADV_ADJ_FOR_ADV', 'ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS', 'Uses an adjective after the verb where an adverb is needed.', '{"question":"She sings ___.","wrong_answer":"beautiful","correct_answer":"beautifully"}'::jsonb, 'Kiswahili uses the same word for both in many sentences.', 'A question like "She sings ___." with "beautiful" among the options.', 'Have the child say both forms aloud and say why one fits: "beautifully", not "beautiful".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS.M_ADV_KIND_MIX', 'ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS', 'Gives the wrong kind to an adverb of time, place or manner.', '{"question":"Which kind of adverb is \"yesterday\"?","wrong_answer":"manner","correct_answer":"time"}'::jsonb, 'Does not ask the question the adverb answers.', 'A question like "Which kind of adverb is "yesterday"?" with "manner" among the options.', 'Have the child say both forms aloud and say why one fits: "time", not "manner".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS.M_ADV_GOOD_WELL', 'ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS', 'Uses good where well is needed.', '{"question":"He plays football ___.","wrong_answer":"good","correct_answer":"well"}'::jsonb, 'Does not know that good is an adjective.', 'A question like "He plays football ___." with "good" among the options.', 'Have the child say both forms aloud and say why one fits: "well", not "good".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS.M_ADV_FASTLY', 'ENGL.G4.LANGUA.T9_WORD_CLASSES_ADVERBS.ADVERBS', 'Adds -ly to fast, hard or late.', '{"question":"The bus goes ___.","wrong_answer":"fastly","correct_answer":"fast"}'::jsonb, 'Over-uses the -ly rule.', 'A question like "The bus goes ___." with "fastly" among the options.', 'Have the child say both forms aloud and say why one fits: "fast", not "fastly".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS.M_COM_NO_COMMA_LIST', 'ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS', 'Leaves out the commas in a list.', '{"question":"Which is right? Mama bought rice beans and maize.","wrong_answer":"Mama bought rice beans and maize.","correct_answer":"Mama bought rice, beans and maize."}'::jsonb, 'Reads the list as one run of words.', 'A question like "Which is right? Mama bought rice beans and maize." with "Mama bought rice beans and maize." among the options.', 'Have the child say both forms aloud and say why one fits: "Mama bought rice, beans and maize.", not "Mama bought rice beans and maize.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS.M_COM_AFTER_LAST', 'ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS', 'Puts a comma after the last item.', '{"question":"Which is right? I like mangoes, oranges, and bananas,","wrong_answer":"I like mangoes, oranges, bananas,","correct_answer":"I like mangoes, oranges and bananas."}'::jsonb, 'Thinks every item needs a comma after it.', 'A question like "Which is right? I like mangoes, oranges, and bananas," with "I like mangoes, oranges, bananas," among the options.', 'Have the child say both forms aloud and say why one fits: "I like mangoes, oranges and bananas.", not "I like mangoes, oranges, bananas,".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS.M_COM_SPLIT_SENTENCE', 'ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS', 'Puts a comma between who and what they do.', '{"question":"Which is right? Wafula, kicked the ball.","wrong_answer":"Wafula, kicked the ball.","correct_answer":"Wafula kicked the ball."}'::jsonb, 'Uses a comma as a breathing mark.', 'A question like "Which is right? Wafula, kicked the ball." with "Wafula, kicked the ball." among the options.', 'Have the child say both forms aloud and say why one fits: "Wafula kicked the ball.", not "Wafula, kicked the ball.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS.M_COM_FULL_STOP_LIST', 'ENGL.G4.WRITIN.T9_PUNCTUATION.COMMAS', 'Uses full stops between the items of a list.', '{"question":"Which is right? We saw lions. zebras. and giraffes.","wrong_answer":"We saw lions. zebras. and giraffes.","correct_answer":"We saw lions, zebras and giraffes."}'::jsonb, 'Does not know the comma has its own job in lists.', 'A question like "Which is right? We saw lions. zebras. and giraffes." with "We saw lions. zebras. and giraffes." among the options.', 'Have the child say both forms aloud and say why one fits: "We saw lions, zebras and giraffes.", not "We saw lions. zebras. and giraffes.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS.M_QMK_FULL_STOP', 'ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS', 'Ends a question with a full stop.', '{"question":"Which is right? Where is the book.","wrong_answer":"Where is the book.","correct_answer":"Where is the book?"}'::jsonb, 'Reads the question aloud with a rising voice but writes the usual end mark.', 'A question like "Which is right? Where is the book." with "Where is the book." among the options.', 'Have the child say both forms aloud and say why one fits: "Where is the book?", not "Where is the book.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS.M_QMK_STATEMENT', 'ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS', 'Ends a statement with a question mark because it has a question word in it.', '{"question":"Which is right? I do not know where he lives?","wrong_answer":"I do not know where he lives?","correct_answer":"I do not know where he lives."}'::jsonb, 'Sees the word where and thinks a question mark is needed.', 'A question like "Which is right? I do not know where he lives?" with "I do not know where he lives?" among the options.', 'Have the child say both forms aloud and say why one fits: "I do not know where he lives.", not "I do not know where he lives?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS.M_QMK_COMMA', 'ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS', 'Ends a question with a comma.', '{"question":"Which is right? Are you hungry,","wrong_answer":"Are you hungry,","correct_answer":"Are you hungry?"}'::jsonb, 'Does not know a comma cannot end a sentence.', 'A question like "Which is right? Are you hungry," with "Are you hungry," among the options.', 'Have the child say both forms aloud and say why one fits: "Are you hungry?", not "Are you hungry,".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS.M_QMK_NO_MARK', 'ENGL.G4.WRITIN.T9_PUNCTUATION.QUESTION_MARKS', 'Leaves the end mark out.', '{"question":"Which is right? What is your name","wrong_answer":"What is your name","correct_answer":"What is your name?"}'::jsonb, 'Forgets the mark in quick writing.', 'A question like "Which is right? What is your name" with "What is your name" among the options.', 'Have the child say both forms aloud and say why one fits: "What is your name?", not "What is your name".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS.M_HYG_NEAR_MEANING', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS', 'Picks a hygiene word that is near in meaning but wrong.', '{"question":"Washing your hands kills ___ that cause diseases.","wrong_answer":"rubbish","correct_answer":"germs"}'::jsonb, 'Mixes up words in the same topic.', 'A question like "Washing your hands kills ___ that cause diseases." with "rubbish" among the options.', 'Have the child say both forms aloud and say why one fits: "germs", not "rubbish".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS.M_HYG_DISINFECT', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS', 'Thinks disinfect means to make something smell nice.', '{"question":"We ___ the toilet with a strong cleaner to kill germs.","wrong_answer":"perfume","correct_answer":"disinfect"}'::jsonb, 'Does not know the meaning.', 'A question like "We ___ the toilet with a strong cleaner to kill germs." with "perfume" among the options.', 'Have the child say both forms aloud and say why one fits: "disinfect", not "perfume".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS.M_HYG_LATRINE', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS', 'Mixes up latrine and drainage.', '{"question":"A ___ is a place to dispose of human waste.","wrong_answer":"drainage","correct_answer":"latrine"}'::jsonb, 'Does not know the words.', 'A question like "A ___ is a place to dispose of human waste." with "drainage" among the options.', 'Have the child say both forms aloud and say why one fits: "latrine", not "drainage".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M4_IP_HEY', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Interrupts with Hey or Wait.', '{"question":"The teacher is talking and you must leave for the clinic. What do you say?","wrong_answer":"Hey, wait!","correct_answer":"Excuse me, teacher, may I go to the clinic?"}'::jsonb, 'The child knows the need is real and forgets the polite words.', 'Offer "Hey, wait!" beside "Excuse me, teacher, may I go to the clinic?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with Excuse me.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M4_IP_NO_PAUSE', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Interrupts in the middle of a sentence.', '{"question":"When is the best time to interrupt?","wrong_answer":"any time I need to","correct_answer":"when the speaker pauses"}'::jsonb, 'The child does not wait for a natural break.', 'Offer "any time I need to" beside "when the speaker pauses" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Wait for a pause, then speak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M4_IP_SORRY_ONLY', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Says only sorry and then speaks, as if apologising.', '{"question":"Which is a polite interruption?","wrong_answer":"Sorry. I want water.","correct_answer":"Sorry to interrupt, but may I get some water?"}'::jsonb, 'Sorry is used alone, without the request.', 'Offer "Sorry. I want water." beside "Sorry to interrupt, but may I get some water?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sorry to interrupt, but may I ...?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY.M4_IP_COMMAND', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.INTERRUPT_POLITELY', 'Gives an order after interrupting.', '{"question":"Interrupt your mother on the phone to ask for the key.","wrong_answer":"Excuse me. Give me the key.","correct_answer":"Excuse me, may I have the key, please?"}'::jsonb, 'Polite opening, but the request is a command.', 'Offer "Excuse me. Give me the key." beside "Excuse me, may I have the key, please?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask with may I or could you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS.M4_HYG_GERMS_DIRT', 'ENGL.G4.LISTEN.T10_PRONUNCIATION_AND_VO.HYGIENE_WORDS', 'Thinks germs are dirt that can be seen.', '{"question":"Your hands look clean after football. Should you still wash them?","wrong_answer":"No, they are clean","correct_answer":"Yes, germs are too small to see"}'::jsonb, 'Germs are pictured as visible dirt.', 'Offer "No, they are clean" beside "Yes, germs are too small to see" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Germs are too small to see: wash with soap anyway.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CNJ_BUT_FOR_AND', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses but where the two parts agree.', '{"question":"Ali likes tea ___ coffee.","wrong_answer":"but","correct_answer":"and"}'::jsonb, 'Thinks every joining word is but.', 'A question like "Ali likes tea ___ coffee." with "but" among the options.', 'Have the child say both forms aloud and say why one fits: "and", not "but".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CNJ_BECAUSE_SO', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Swaps because and so.', '{"question":"It was raining, ___ we stayed inside.","wrong_answer":"because","correct_answer":"so"}'::jsonb, 'Mixes up a reason with a result.', 'A question like "It was raining, ___ we stayed inside." with "because" among the options.', 'Have the child say both forms aloud and say why one fits: "so", not "because".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CNJ_AND_FOR_BUT', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses and where the two ideas go against each other.', '{"question":"I wanted to play, ___ I was tired.","wrong_answer":"and","correct_answer":"but"}'::jsonb, 'Uses and as the all-purpose joining word.', 'A question like "I wanted to play, ___ I was tired." with "and" among the options.', 'Have the child say both forms aloud and say why one fits: "but", not "and".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CNJ_AND_FOR_OR', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses and where there is a choice.', '{"question":"Would you like tea ___ juice?","wrong_answer":"and","correct_answer":"or"}'::jsonb, 'Does not hear the choice.', 'A question like "Would you like tea ___ juice?" with "and" among the options.', 'Have the child say both forms aloud and say why one fits: "or", not "and".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CNJ_OR_FOR_AND', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses or where both things happen.', '{"question":"Mama bought rice ___ beans.","wrong_answer":"or","correct_answer":"and"}'::jsonb, 'Does not hear the choice in or.', 'A question like "Mama bought rice ___ beans." with "or" among the options.', 'Have the child say both forms aloud and say why one fits: "and", not "or".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS.M_CNJ_DOUBLE', 'ENGL.G4.LANGUA.T10_WORD_CLASS_CONJUNCTI.CONJUNCTIONS', 'Uses two joining words for one link.', '{"question":"Although it was late, ___ we went on.","wrong_answer":"but","correct_answer":"no joining word"}'::jsonb, 'Copies the two-word pattern of speech.', 'A question like "Although it was late, ___ we went on." with "but" among the options.', 'Have the child say both forms aloud and say why one fits: "no joining word", not "but".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS.M_DES_TELLS_STORY', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS', 'Writes what happened instead of what the thing is like.', '{"question":"Which sentence is part of a description of a market?","wrong_answer":"Yesterday I went to the market and bought a hat.","correct_answer":"The market is noisy and smells of fresh fruit."}'::jsonb, 'Confuses a description with a story.', 'A question like "Which sentence is part of a description of a market?" with "Yesterday I went to the market and bought a hat." among the options.', 'Have the child say both forms aloud and say why one fits: "The market is noisy and smells of fresh fruit.", not "Yesterday I went to the market and bought a hat.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS.M_DES_ONE_SENSE', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS', 'Uses only what can be seen.', '{"question":"Which sentence uses a sense other than sight?","wrong_answer":"The market is big.","correct_answer":"The market smells of fresh fruit."}'::jsonb, 'Thinks describing means describing how it looks.', 'A question like "Which sentence uses a sense other than sight?" with "The market is big." among the options.', 'Have the child say both forms aloud and say why one fits: "The market smells of fresh fruit.", not "The market is big.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS.M_DES_PART_MIX', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS', 'Mixes up the introduction and the conclusion.', '{"question":"Which part names what you will describe?","wrong_answer":"the conclusion","correct_answer":"the introduction"}'::jsonb, 'Does not know the parts.', 'A question like "Which part names what you will describe?" with "the conclusion" among the options.', 'Have the child say both forms aloud and say why one fits: "the introduction", not "the conclusion".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M4_DC_STORY', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Tells what happened instead of describing.', '{"question":"Describe your classroom. Which sentence fits?","wrong_answer":"Yesterday we had a test in our classroom.","correct_answer":"Our classroom has bright charts on every wall."}'::jsonb, 'Narrative writing is the most practised.', 'Offer "Yesterday we had a test in our classroom." beside "Our classroom has bright charts on every wall." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describe how it looks, sounds and feels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M4_DC_SIGHT_ONLY', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Describes only what is seen.', '{"question":"Add another sense to: \"The market is big and busy.\"","wrong_answer":"The market is very big.","correct_answer":"The market smells of ripe mangoes and fish."}'::jsonb, 'Seeing is the sense the child notices first.', 'Offer "The market is very big." beside "The market smells of ripe mangoes and fish." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use sound, smell and touch as well as sight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M4_DC_NICE', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Uses the same weak adjectives (nice, good, big) again and again.', '{"question":"Improve: \"The garden is nice and the flowers are nice.\"","wrong_answer":"The garden is nice and the flowers are nice.","correct_answer":"The garden is green and the flowers are bright red."}'::jsonb, 'A small stock of adjectives.', 'Offer "The garden is nice and the flowers are nice." beside "The garden is green and the flowers are bright red." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose an exact adjective: bright, tall, noisy, smooth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION.M4_DC_NO_CONCLUSION', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_COMPOSITION', 'Ends without a conclusion.', '{"question":"What should the last sentence do?","wrong_answer":"add one more detail","correct_answer":"say how the writer feels about the place"}'::jsonb, 'The child stops when the details run out.', 'Offer "add one more detail" beside "say how the writer feels about the place" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'End by saying what the place means to you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS.M4_DES_NO_ORDER', 'ENGL.G4.WRITIN.T10_CREATIVE_WRITING.DESCRIPTIVE_PARTS', 'Describes details in a jumbled order.', '{"question":"Best order for describing a house?","wrong_answer":"roof, door, roof again, garden","correct_answer":"outside to inside, or top to bottom"}'::jsonb, 'Details are written as they come to mind.', 'Offer "roof, door, roof again, garden" beside "outside to inside, or top to bottom" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose an order: outside to inside, or top to bottom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS.M_SPT_NEAR_MEANING', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS', 'Picks a sports word that is near in meaning but wrong.', '{"question":"The ___ blows the whistle to start the match.","wrong_answer":"goalkeeper","correct_answer":"referee"}'::jsonb, 'Mixes up the people in a game.', 'A question like "The ___ blows the whistle to start the match." with "goalkeeper" among the options.', 'Have the child say both forms aloud and say why one fits: "referee", not "goalkeeper".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS.M_SPT_TROPHY_TOURNAMENT', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS', 'Mixes up trophy and tournament.', '{"question":"Our team won the ___ at the end of the tournament.","wrong_answer":"tournament","correct_answer":"trophy"}'::jsonb, 'Does not know the two words.', 'A question like "Our team won the ___ at the end of the tournament." with "tournament" among the options.', 'Have the child say both forms aloud and say why one fits: "trophy", not "tournament".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS.M_SPT_OPPONENT_TEAMMATE', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS', 'Mixes up opponent and teammate.', '{"question":"The player on the other team is my ___.","wrong_answer":"teammate","correct_answer":"opponent"}'::jsonb, 'Does not know the words.', 'A question like "The player on the other team is my ___." with "teammate" among the options.', 'Have the child say both forms aloud and say why one fits: "opponent", not "teammate".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M4_NC_NOD', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Reads a nod as no, or a head shake as yes.', '{"question":"Your teacher nods when you answer. What does it mean?","wrong_answer":"You are wrong.","correct_answer":"You are right; go on."}'::jsonb, 'Gestures are not taught and are guessed.', 'Offer "You are wrong." beside "You are right; go on." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A nod means yes or I agree.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M4_NC_FROWN', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Reads a frown as happiness or as nothing.', '{"question":"Your friend frowns while you explain the game. She is probably ...","wrong_answer":"happy","correct_answer":"confused or unhappy"}'::jsonb, 'The child watches the words, not the face.', 'Offer "happy" beside "confused or unhappy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the face: a frown shows a problem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M4_NC_TONE_WORDS', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Trusts the words and ignores the tone of voice.', '{"question":"Juma says \"Great, thanks a lot\" in an angry voice after his pen breaks. He feels ...","wrong_answer":"happy","correct_answer":"annoyed"}'::jsonb, 'The child reads only the dictionary meaning of the words.', 'Offer "happy" beside "annoyed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The tone tells you the feeling, even when the words say something else.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES.M4_NC_POINTING', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.NONVERBAL_CUES', 'Points at an older person with a finger while talking about them.', '{"question":"Which is polite when telling the visitor where the headteacher is?","wrong_answer":"Point at the headteacher with one finger","correct_answer":"Show with an open hand"}'::jsonb, 'The child has not learnt which gestures are rude in Kenyan settings.', 'Offer "Point at the headteacher with one finger" beside "Show with an open hand" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use an open hand to show, not one finger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS.M4_SPT_DRAW_LOSE', 'ENGL.G4.LISTEN.T11_PRONUNCIATION_AND_VO.SPORTS_WORDS', 'Thinks a draw means one team lost.', '{"question":"The score was 1-1. The match was a ...","wrong_answer":"loss","correct_answer":"draw"}'::jsonb, 'A result that is not a win is taken as a loss.', 'Offer "loss" beside "draw" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A draw means both teams scored the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES.M_INT_WHO_FOR_WHAT', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES', 'Uses who for a thing and what for a person.', '{"question":"___ is your teacher?","wrong_answer":"What","correct_answer":"Who"}'::jsonb, 'Does not link the question word to the kind of answer.', 'A question like "___ is your teacher?" with "What" among the options.', 'Have the child say both forms aloud and say why one fits: "Who", not "What".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES.M_INT_WHERE_FOR_WHEN', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES', 'Uses where for a time and when for a place.', '{"question":"___ do we start? At nine o''clock.","wrong_answer":"Where","correct_answer":"When"}'::jsonb, 'Does not listen to the answer.', 'A question like "___ do we start? At nine o''clock." with "Where" among the options.', 'Have the child say both forms aloud and say why one fits: "When", not "Where".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES.M_INT_NO_INVERSION', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES', 'Keeps the statement order in a question.', '{"question":"Where ___ going?","wrong_answer":"you are","correct_answer":"are you"}'::jsonb, 'Kiswahili questions keep the same order with a question word.', 'A question like "Where ___ going?" with "you are" among the options.', 'Have the child say both forms aloud and say why one fits: "are you", not "you are".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES.M_INT_DO_EXTRA', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES', 'Adds do to a question that already has is, are or can.', '{"question":"How ___ you?","wrong_answer":"do are","correct_answer":"are"}'::jsonb, 'Adds do to every question.', 'A question like "How ___ you?" with "do are" among the options.', 'Have the child say both forms aloud and say why one fits: "are", not "do are".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES.M_INT_WHOSE_WHOS', 'ENGL.G4.LANGUA.T11_LANGUAGE_PATTERNS.INTERROGATIVES', 'Writes who''s for whose.', '{"question":"___ bag is this?","wrong_answer":"Who''s","correct_answer":"Whose"}'::jsonb, 'Mixes up two words that sound the same.', 'A question like "___ bag is this?" with "Who''s" among the options.', 'Have the child say both forms aloud and say why one fits: "Whose", not "Who''s".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS.M_SPL_VOWEL_ORDER', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS', 'Swaps the vowels in ie and ei words.', '{"question":"Wanjiru is my best ___.","wrong_answer":"freind","correct_answer":"friend"}'::jsonb, 'Does not remember which vowel comes first.', 'A question like "Wanjiru is my best ___." with "freind" among the options.', 'Have the child say both forms aloud and say why one fits: "friend", not "freind".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS.M_SPL_PHONETIC', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS', 'Spells the word as it sounds.', '{"question":"We stayed home ___ it rained.","wrong_answer":"becos","correct_answer":"because"}'::jsonb, 'Writes what the ear hears.', 'A question like "We stayed home ___ it rained." with "becos" among the options.', 'Have the child say both forms aloud and say why one fits: "because", not "becos".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS.M_SPL_DROPPED_LETTER', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS', 'Leaves out a letter that is not heard.', '{"question":"We have a ___ at school.","wrong_answer":"libary","correct_answer":"library"}'::jsonb, 'Does not say the middle letter.', 'A question like "We have a ___ at school." with "libary" among the options.', 'Have the child say both forms aloud and say why one fits: "library", not "libary".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS.M_SPL_EXTRA_LETTER', 'ENGL.G4.WRITIN.T11_MECHANICS_OF_WRITING.MISSPELT_WORDS', 'Leaves out or changes letters in a long vowel group.', '{"question":"The flowers are ___.","wrong_answer":"beutiful","correct_answer":"beautiful"}'::jsonb, 'Mixes up the vowel group.', 'A question like "The flowers are ___." with "beutiful" among the options.', 'Have the child say both forms aloud and say why one fits: "beautiful", not "beutiful".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS.M_ENV_NEAR_MEANING', 'ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS', 'Picks an environment word that is near in meaning but wrong.', '{"question":"To ___ plastic is to make it into something new.","wrong_answer":"litter","correct_answer":"recycle"}'::jsonb, 'Mixes up words in the same topic.', 'A question like "To ___ plastic is to make it into something new." with "litter" among the options.', 'Have the child say both forms aloud and say why one fits: "recycle", not "litter".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS.M_ENV_POLLUTION', 'ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS', 'Thinks pollution is a kind of plant.', '{"question":"___ is the dirt that harms air, water or soil.","wrong_answer":"Compost","correct_answer":"Pollution"}'::jsonb, 'Does not know the word.', 'A question like "___ is the dirt that harms air, water or soil." with "Compost" among the options.', 'Have the child say both forms aloud and say why one fits: "Pollution", not "Compost".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS.M_ENV_CONSERVE', 'ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS', 'Thinks conserve means to use up.', '{"question":"We should ___ water, not waste it.","wrong_answer":"pollute","correct_answer":"conserve"}'::jsonb, 'Does not know the word.', 'A question like "We should ___ water, not waste it." with "pollute" among the options.', 'Have the child say both forms aloud and say why one fits: "conserve", not "pollute".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS.M4_ENV_RECYCLE_REUSE', 'ENGL.G4.LISTEN.T12_PRONUNCIATION_AND_VO.ENVIRONMENT_WORDS', 'Swaps recycle and reuse.', '{"question":"You use an old jar to keep pens. You ... it.","wrong_answer":"recycle","correct_answer":"reuse"}'::jsonb, 'Both are ways to waste less.', 'Offer "recycle" beside "reuse" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Reuse means use again; recycle means make it into something new.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS.M_PRV_LITERAL', 'ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS', 'Reads a proverb as only about its animals or things.', '{"question":"Haste makes waste means:","wrong_answer":"people who hurry waste water","correct_answer":"doing a thing too fast can spoil it"}'::jsonb, 'Takes the words at face value.', 'A question like "Haste makes waste means:" with "people who hurry waste water" among the options.', 'Have the child say both forms aloud and say why one fits: "doing a thing too fast can spoil it", not "people who hurry waste water".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS.M_PRV_OPPOSITE', 'ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS', 'Gives the opposite lesson.', '{"question":"Slow and steady wins the race means:","wrong_answer":"be fast to win","correct_answer":"keep going carefully and you will succeed"}'::jsonb, 'Does not read the whole proverb.', 'A question like "Slow and steady wins the race means:" with "be fast to win" among the options.', 'Have the child say both forms aloud and say why one fits: "keep going carefully and you will succeed", not "be fast to win".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS.M_PRV_UNRELATED', 'ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS', 'Picks a lesson that has nothing to do with the proverb.', '{"question":"A stitch in time saves nine means:","wrong_answer":"sewing is hard","correct_answer":"fix a small problem early to avoid a big one"}'::jsonb, 'Guesses from one word.', 'A question like "A stitch in time saves nine means:" with "sewing is hard" among the options.', 'Have the child say both forms aloud and say why one fits: "fix a small problem early to avoid a big one", not "sewing is hard".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS.M_PRV_WRONG_WORD', 'ENGL.G4.READIN.T12_1_INTENSIVE_READING.PROVERBS', 'Finishes a proverb with a word that sounds right but is not.', '{"question":"Easy come, easy ___.","wrong_answer":"stay","correct_answer":"go"}'::jsonb, 'Remembers the idea and not the exact words.', 'A question like "Easy come, easy ___." with "stay" among the options.', 'Have the child say both forms aloud and say why one fits: "go", not "stay".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT.M_PPF_PAST_FORM', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT', 'Uses the simple past form after have or has.', '{"question":"I have ___ my lunch.","wrong_answer":"ate","correct_answer":"eaten"}'::jsonb, 'Does not know the past participle of irregular verbs.', 'A question like "I have ___ my lunch." with "ate" among the options.', 'Have the child say both forms aloud and say why one fits: "eaten", not "ate".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT.M_PPF_HAS_HAVE', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT', 'Mixes have and has.', '{"question":"She ___ finished her work.","wrong_answer":"have","correct_answer":"has"}'::jsonb, 'Does not match the helping word to the subject.', 'A question like "She ___ finished her work." with "have" among the options.', 'Have the child say both forms aloud and say why one fits: "has", not "have".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT.M_PPF_BASE_VERB', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT', 'Uses the plain verb after have or has.', '{"question":"They have ___ home.","wrong_answer":"go","correct_answer":"gone"}'::jsonb, 'Leaves out the past participle ending.', 'A question like "They have ___ home." with "go" among the options.', 'Have the child say both forms aloud and say why one fits: "gone", not "go".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT.M_PPF_WITH_PAST_TIME', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PRESENT_PERFECT', 'Uses have or has with yesterday, last week or an exact past time.', '{"question":"I ___ him yesterday.","wrong_answer":"have seen","correct_answer":"saw"}'::jsonb, 'Thinks have or has is simply a past marker.', 'A question like "I ___ him yesterday." with "have seen" among the options.', 'Have the child say both forms aloud and say why one fits: "saw", not "have seen".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT.M_PAF_HAD_MISSING', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT', 'Uses the simple past for both events.', '{"question":"The bus ___ left before I arrived.","wrong_answer":"was","correct_answer":"had"}'::jsonb, 'Does not mark which event came first.', 'A question like "The bus ___ left before I arrived." with "was" among the options.', 'Have the child say both forms aloud and say why one fits: "had", not "was".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT.M_PAF_HAVE_FOR_HAD', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT', 'Uses have or has where had is needed.', '{"question":"When I got home, Mum ___ cooked.","wrong_answer":"has","correct_answer":"had"}'::jsonb, 'Does not move the helping word into the past.', 'A question like "When I got home, Mum ___ cooked." with "has" among the options.', 'Have the child say both forms aloud and say why one fits: "had", not "has".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT.M_PAF_BASE_VERB', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT', 'Uses the plain verb after had.', '{"question":"She had ___ her homework.","wrong_answer":"finish","correct_answer":"finished"}'::jsonb, 'Forgets the past participle.', 'A question like "She had ___ her homework." with "finish" among the options.', 'Have the child say both forms aloud and say why one fits: "finished", not "finish".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT.M_PAF_WRONG_ORDER', 'ENGL.G4.LANGUA.T12_WORD_CLASSES_VERB_AS.PAST_PERFECT', 'Puts had on the event that happened second.', '{"question":"Which happened first? Wanjiru had left when I arrived.","wrong_answer":"I arrived","correct_answer":"Wanjiru left"}'::jsonb, 'Does not see that had marks the earlier event.', 'A question like "Which happened first? Wanjiru had left when I arrived." with "I arrived" among the options.', 'Have the child say both forms aloud and say why one fits: "Wanjiru left", not "I arrived".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS.M_DIA_NO_DATE', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS', 'Leaves the date out.', '{"question":"What does every diary entry start with?","wrong_answer":"a title","correct_answer":"the date"}'::jsonb, 'Thinks the diary is only for reading by the writer.', 'A question like "What does every diary entry start with?" with "a title" among the options.', 'Have the child say both forms aloud and say why one fits: "the date", not "a title".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS.M_DIA_LETTER_FORMAT', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS', 'Writes the diary as a letter to a person.', '{"question":"Which is the best start of a diary entry?","wrong_answer":"Dear Mum, how are you?","correct_answer":"Monday, 4th March. Dear Diary,"}'::jsonb, 'Mixes up the friendly letter and the diary.', 'A question like "Which is the best start of a diary entry?" with "Dear Mum, how are you?" among the options.', 'Have the child say both forms aloud and say why one fits: "Monday, 4th March. Dear Diary,", not "Dear Mum, how are you?".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS.M_DIA_THIRD_PERSON', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS', 'Writes about himself or herself as he or she.', '{"question":"Which sentence is in the right voice?","wrong_answer":"Wanjiru woke up early.","correct_answer":"I woke up early."}'::jsonb, 'Writes as in a story told by someone else.', 'A question like "Which sentence is in the right voice?" with "Wanjiru woke up early." among the options.', 'Have the child say both forms aloud and say why one fits: "I woke up early.", not "Wanjiru woke up early.".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS.M_DIA_NO_FEELINGS', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_PARTS', 'Writes only a list of events, with no feelings.', '{"question":"What else does a diary entry have besides what happened?","wrong_answer":"a list of names","correct_answer":"how the writer felt"}'::jsonb, 'Thinks a diary is a record only.', 'A question like "What else does a diary entry have besides what happened?" with "a list of names" among the options.', 'Have the child say both forms aloud and say why one fits: "how the writer felt", not "a list of names".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING.M4_DW_NO_DATE', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING', 'Leaves out the date.', '{"question":"What must a diary entry begin with?","wrong_answer":"a title","correct_answer":"the day and date"}'::jsonb, 'The child does not see why the date matters.', 'Offer "a title" beside "the day and date" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every entry starts with the date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING.M4_DW_FUTURE', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING', 'Writes plans for tomorrow instead of what happened.', '{"question":"Which belongs in a diary entry for today?","wrong_answer":"Tomorrow I will play.","correct_answer":"Today I helped Mum plant beans."}'::jsonb, 'The child confuses a diary with a timetable.', 'Offer "Tomorrow I will play." beside "Today I helped Mum plant beans." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A diary records what happened today.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING.M4_DW_THIRD_PERSON', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING', 'Writes about himself or herself as he or she.', '{"question":"Which is a diary sentence?","wrong_answer":"Baraka went to church.","correct_answer":"I went to church."}'::jsonb, 'Story writing is carried over.', 'Offer "Baraka went to church." beside "I went to church." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A diary uses I.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING.M4_DW_EVENTS_ONLY', 'ENGL.G4.WRITIN.T12_GUIDED_COMPOSITION.DIARY_WRITING', 'Lists events with no feelings.', '{"question":"Add a feeling to: \"I went to the clinic.\"","wrong_answer":"I went to the clinic. I came back.","correct_answer":"I went to the clinic. I was scared of the injection."}'::jsonb, 'The child thinks only facts count.', 'Offer "I went to the clinic. I came back." beside "I went to the clinic. I was scared of the injection." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say how you felt about what happened.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS.M_MON_EARN_SAVE', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS', 'Swaps earn and save.', '{"question":"Mama ___ money every month to buy a cow later.","wrong_answer":"earns","correct_answer":"saves"}'::jsonb, 'Does not tell getting money from keeping it.', 'A question like "Mama ___ money every month to buy a cow later." with "earns" among the options.', 'Have the child say both forms aloud and say why one fits: "saves", not "earns".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS.M_MON_BORROW_LEND', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS', 'Swaps borrow and lend.', '{"question":"Can I ___ your pen? I will return it.","wrong_answer":"lend","correct_answer":"borrow"}'::jsonb, 'Does not tell who takes and who gives.', 'A question like "Can I ___ your pen? I will return it." with "lend" among the options.', 'Have the child say both forms aloud and say why one fits: "borrow", not "lend".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS.M_MON_NEAR_MEANING', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS', 'Picks a money word that is near in meaning but wrong.', '{"question":"A ___ helps a family plan how to spend its money.","wrong_answer":"price","correct_answer":"budget"}'::jsonb, 'Mixes up words in the same topic.', 'A question like "A ___ helps a family plan how to spend its money." with "price" among the options.', 'Have the child say both forms aloud and say why one fits: "budget", not "price".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS.M_MON_PRICE_CHANGE', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.MONEY_WORDS', 'Mixes up price and change.', '{"question":"The ___ of the book is 80 shillings.","wrong_answer":"change","correct_answer":"price"}'::jsonb, 'Treats the money words as the same.', 'A question like "The ___ of the book is 80 shillings." with "change" among the options.', 'Have the child say both forms aloud and say why one fits: "price", not "change".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS.M_SIL_NEIGHBOUR', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS', 'Picks the letter beside the silent one.', '{"question":"Which letter is silent in \"knife\"?","wrong_answer":"n","correct_answer":"k"}'::jsonb, 'Does not say the word slowly.', 'A question like "Which letter is silent in "knife"?" with "n" among the options.', 'Have the child say both forms aloud and say why one fits: "k", not "n".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS.M_SIL_NONE', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS', 'Thinks every letter is sounded.', '{"question":"Which letter is silent in \"write\"?","wrong_answer":"none","correct_answer":"w"}'::jsonb, 'Does not know silent letters.', 'A question like "Which letter is silent in "write"?" with "none" among the options.', 'Have the child say both forms aloud and say why one fits: "w", not "none".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS.M_SIL_END_E', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS', 'Thinks the silent letter is always the last letter.', '{"question":"Which letter is silent in \"lamb\"?","wrong_answer":"m","correct_answer":"b"}'::jsonb, 'Has learnt silent e at the end.', 'A question like "Which letter is silent in "lamb"?" with "m" among the options.', 'Have the child say both forms aloud and say why one fits: "b", not "m".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT.M4_VB_VERY_COMPARATIVE', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT', 'Uses very with a comparative (very cheaper).', '{"question":"The shoes are very ... but they are expensive. (nice)","wrong_answer":"nicer","correct_answer":"nice"}'::jsonb, 'Two ways of making a stronger meaning are mixed.', 'Offer "nicer" beside "nice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Very goes with the plain adjective: very nice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT.M4_VB_TOO_FOR_VERY', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT', 'Uses too where very is meant.', '{"question":"The mangoes are ... sweet but they are small.","wrong_answer":"too","correct_answer":"very"}'::jsonb, 'In Kenyan English too often means very (too nice), but in standard English too means more than is wanted.', 'Offer "too" beside "very" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Very means a lot; too means more than is good.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT.M4_VB_NO_CONTRAST', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT', 'Uses but between two ideas that agree.', '{"question":"Which sentence is correct?","wrong_answer":"The bag is very strong but it is good.","correct_answer":"The bag is very strong but it is heavy."}'::jsonb, 'But is treated as a plain joining word.', 'Offer "The bag is very strong but it is good." beside "The bag is very strong but it is heavy." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'But needs two ideas that pull different ways.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT.M4_VB_VERY_MUCH', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.VERY_BUT', 'Says very much before an adjective.', '{"question":"The book is ... interesting but it is long.","wrong_answer":"very much","correct_answer":"very"}'::jsonb, 'Very much is learnt with thank you and spread to adjectives.', 'Offer "very much" beside "very" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Very goes alone before an adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS.M4_SIL_SPELL_SAY', 'ENGL.G4.LISTEN.T13_PRONUNCIATION_AND_VO.SILENT_LETTERS', 'Pronounces the silent letter because it is written.', '{"question":"Say: knife","wrong_answer":"k-nife","correct_answer":"nife"}'::jsonb, 'Reading by spelling: every letter is sounded.', 'Offer "k-nife" beside "nife" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The k in kn is silent: knife, knee, know.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION.M_PRE_IN_ON', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION', 'Mixes up in and on.', '{"question":"The cup is ___ the table.","wrong_answer":"in","correct_answer":"on"}'::jsonb, 'Does not picture the position.', 'A question like "The cup is ___ the table." with "in" among the options.', 'Have the child say both forms aloud and say why one fits: "on", not "in".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION.M_PRE_BETWEEN_AMONG', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION', 'Uses between for three or more things, or among for two.', '{"question":"The ball is ___ the two boys.","wrong_answer":"among","correct_answer":"between"}'::jsonb, 'Does not count the things.', 'A question like "The ball is ___ the two boys." with "among" among the options.', 'Have the child say both forms aloud and say why one fits: "between", not "among".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION.M_PRE_UNDER_OVER', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION', 'Picks the opposite preposition.', '{"question":"The cat is ___ the bed (hiding below it).","wrong_answer":"on","correct_answer":"under"}'::jsonb, 'Does not picture where the thing is.', 'A question like "The cat is ___ the bed (hiding below it)." with "on" among the options.', 'Have the child say both forms aloud and say why one fits: "under", not "on".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION.M_PRE_FRONT_BEHIND', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_POSITION', 'Mixes up in front of and behind.', '{"question":"Juma stood ___ Achieng at the end of the line.","wrong_answer":"in front of","correct_answer":"behind"}'::jsonb, 'Does not picture the line.', 'A question like "Juma stood ___ Achieng at the end of the line." with "in front of" among the options.', 'Have the child say both forms aloud and say why one fits: "behind", not "in front of".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION.M_PRD_TO_INTO', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION', 'Uses to where into (going inside) is needed.', '{"question":"He ran ___ the room.","wrong_answer":"to","correct_answer":"into"}'::jsonb, 'Does not feel the idea of going inside.', 'A question like "He ran ___ the room." with "to" among the options.', 'Have the child say both forms aloud and say why one fits: "into", not "to".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION.M_PRD_AT_FOR_TO', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION', 'Uses at after go.', '{"question":"We go ___ school every day.","wrong_answer":"at","correct_answer":"to"}'::jsonb, 'Mixes the place and the movement words.', 'A question like "We go ___ school every day." with "at" among the options.', 'Have the child say both forms aloud and say why one fits: "to", not "at".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION.M_PRD_TO_HOME', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION', 'Writes to before home.', '{"question":"I went ___ after school.","wrong_answer":"to home","correct_answer":"home"}'::jsonb, 'Copies the pattern "go to school".', 'A question like "I went ___ after school." with "to home" among the options.', 'Have the child say both forms aloud and say why one fits: "home", not "to home".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION.M_PRD_THROUGH_ACROSS', 'ENGL.G4.LANGUA.T13_WORD_CLASS_PREPOSITI.PREP_DIRECTION', 'Mixes through and across.', '{"question":"The goat ran ___ the road to the other side.","wrong_answer":"through","correct_answer":"across"}'::jsonb, 'Does not picture the movement.', 'A question like "The goat ran ___ the road to the other side." with "through" among the options.', 'Have the child say both forms aloud and say why one fits: "across", not "through".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS.M_DBL_SINGLE', 'ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS', 'Writes one consonant where there are two.', '{"question":"Mama drinks ___ every morning.","wrong_answer":"cofee","correct_answer":"coffee"}'::jsonb, 'Does not hear the two letters.', 'A question like "Mama drinks ___ every morning." with "cofee" among the options.', 'Have the child say both forms aloud and say why one fits: "coffee", not "cofee".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS.M_DBL_PHONETIC', 'ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS', 'Spells the word as it sounds.', '{"question":"The ___ ran into its hole.","wrong_answer":"rabbet","correct_answer":"rabbit"}'::jsonb, 'Writes what the ear hears and picks a wrong vowel.', 'A question like "The ___ ran into its hole." with "rabbet" among the options.', 'Have the child say both forms aloud and say why one fits: "rabbit", not "rabbet".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS.M_DBL_EXTRA', 'ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS', 'Doubles a letter that is single.', '{"question":"I wrote a ___ to my aunt.","wrong_answer":"lettter","correct_answer":"letter"}'::jsonb, 'Over-corrects after learning double letters.', 'A question like "I wrote a ___ to my aunt." with "lettter" among the options.', 'Have the child say both forms aloud and say why one fits: "letter", not "lettter".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS.M4_DBL_ING_NO_DOUBLE', 'ENGL.G4.WRITIN.T13_SPELLING.DOUBLE_CONSONANTS', 'Does not double the last consonant before -ing or -ed.', '{"question":"run + ing","wrong_answer":"runing","correct_answer":"running"}'::jsonb, 'The doubling rule for short vowels is not known.', 'Offer "runing" beside "running" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short vowel and one consonant: double it before -ing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
